fn draw_terminal_status_badges(ui: &mut Ui, ai_badge: &AiBadgeModel) -> TerminalStatusBadgeLayout {
    let badge_visual = ai_badge_visual(
        ai_badge.status,
        ai_badge.codex_normalized_status,
        ai_badge.opencode_normalized_status,
        ai_badge.claude_normalized_status,
        ai_badge.codex_attention_pending,
        ai_badge.codex_attention_reason,
        ai_badge.opencode_attention_pending,
        ai_badge.opencode_attention_reason,
    );

    // Draw badge if visual is available
    let ai_response = badge_visual.map(|_| draw_ai_badge(ui, ai_badge));

    #[cfg(test)]
    let ai_rect = ai_response.as_ref().map(|response| response.rect);
    if ai_response.is_some() {
        ui.add_space(4.0);
    }

    TerminalStatusBadgeLayout {
        #[cfg(test)]
        ai_rect,
    }
}

struct TerminalRenderModel {
    layout_job: LayoutJob,
    cursor_overlay: Option<TerminalCursorOverlay>,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
struct TerminalCursorOverlay {
    shape: TerminalCursorShape,
    row: usize,
    column: usize,
    width_columns: usize,
    color: Color32,
}

#[derive(Debug, Clone)]
struct DirectoryNode {
    name: String,
    path: PathBuf,
    is_dir: bool,
    is_placeholder: bool,
    /// True if this directory was deferred during fast indexing and should be loaded on demand.
    is_deferred: bool,
    children: Vec<DirectoryNode>,
}

/// Snapshot flags for why the directory index was truncated or partial.
#[derive(Debug, Clone, Default)]
struct DirectoryIndexTruncationFlags {
    node_limit: bool,
    depth_limit: bool,
    time_budget: bool,
    deferred_directories: bool,
}

#[derive(Debug, Clone)]
struct DirectoryIndexSnapshot {
    root: DirectoryNode,
    loading: bool,
    last_error: Option<String>,
    partial_warning: Option<String>,
    truncation: DirectoryIndexTruncationFlags,
}

/// Directory index event for full or subtree results.
#[derive(Debug, Clone)]
enum DirectoryIndexEvent {
    /// Full project index result.
    Full {
        project_id: u64,
        generation: u64,
        snapshot: DirectoryIndexSnapshot,
    },
    /// Subtree result for a specific deferred directory.
    Subtree {
        project_id: u64,
        generation: u64,
        target_path: PathBuf,
        children: Vec<DirectoryNode>,
        last_error: Option<String>,
        partial_warning: Option<String>,
        truncation: DirectoryIndexTruncationFlags,
    },
}

