fn with_settings_text_edit_chrome<R>(ui: &mut Ui, add_contents: impl FnOnce(&mut Ui) -> R) -> R {
    let chrome = settings_text_edit_chrome();
    ui.scope(|ui| {
        let style = ui.style_mut();
        style.visuals.extreme_bg_color = chrome.fill;
        style.visuals.selection.stroke = chrome.focus_stroke;
        style.visuals.widgets.inactive.bg_fill = chrome.fill;
        style.visuals.widgets.inactive.weak_bg_fill = chrome.fill;
        style.visuals.widgets.inactive.bg_stroke = chrome.stroke;
        style.visuals.widgets.hovered.bg_fill = chrome.fill;
        style.visuals.widgets.hovered.weak_bg_fill = chrome.fill;
        style.visuals.widgets.hovered.bg_stroke = chrome.focus_stroke;
        style.visuals.widgets.active.bg_fill = chrome.fill;
        style.visuals.widgets.active.weak_bg_fill = chrome.fill;
        style.visuals.widgets.active.bg_stroke = chrome.focus_stroke;
        style.visuals.widgets.open.bg_fill = chrome.fill;
        style.visuals.widgets.open.weak_bg_fill = chrome.fill;
        style.visuals.widgets.open.bg_stroke = chrome.focus_stroke;
        add_contents(ui)
    })
    .inner
}

fn capped_hover_text(text: &str, max_chars: usize) -> String {
    let mut result = String::new();
    for (index, ch) in text.chars().enumerate() {
        if index >= max_chars {
            result.push('…');
            break;
        }
        result.push(ch);
    }
    result
}

#[allow(dead_code)]
const RECENT_INPUTS_HOVER_MAX_CHARS: usize = 100;

/// Returns deduplicated recent inputs preserving newest-first order.
/// Identical strings appear only once (first occurrence wins).
#[allow(dead_code)]
fn deduplicated_recent_inputs(recent_inputs: &VecDeque<String>) -> Vec<&String> {
    let mut seen = HashSet::new();
    let mut result = Vec::with_capacity(recent_inputs.len());
    for input in recent_inputs.iter() {
        if seen.insert(input.as_str()) {
            result.push(input);
        }
    }
    result
}

#[allow(dead_code)]
fn recent_inputs_tooltip_text(recent_inputs: &VecDeque<String>) -> String {
    if recent_inputs.is_empty() {
        return String::new();
    }

    let unique = deduplicated_recent_inputs(recent_inputs);
    unique
        .into_iter()
        .map(|input| capped_hover_text(input, RECENT_INPUTS_HOVER_MAX_CHARS))
        .collect::<Vec<_>>()
        .join("\n")
}

fn with_truncation_tooltip(
    ui: &Ui,
    response: egui::Response,
    text: &str,
    _font_id: &FontId,
    _color: Color32,
    available_width: f32,
) -> egui::Response {
    if text.trim().is_empty() {
        return response;
    }

    // Check if text actually exceeds available width
    let galley = WidgetText::from(text.to_owned()).into_galley(
        ui,
        Some(TextWrapMode::Truncate),
        available_width,
        egui::TextStyle::Body,
    );

    if galley.size().x <= available_width {
        // Text fits without truncation, no tooltip needed
        return response;
    }

    // Use fixed width for consistent tooltip sizing
    let tooltip_width = TERMINAL_HOVER_WIDTH.min(ui.available_width().max(240.0));

    response.on_hover_ui(|ui| {
        ui.set_min_width(tooltip_width);
        ui.set_max_width(tooltip_width);
        ui.label(
            egui::RichText::new(capped_hover_text(text, DIRECTORY_ENTRY_TOOLTIP_MAX_CHARS))
                .color(TEXT_PRIMARY),
        );
    })
}

#[allow(dead_code)]
fn source_control_badge_color(state: SourceControlBadgeState) -> Color32 {
    match state {
        SourceControlBadgeState::Clean => Color32::from_rgb(94, 196, 130),
        SourceControlBadgeState::Error => Color32::from_rgb(224, 92, 92),
    }
}

fn source_control_snapshot_has_display_data(snapshot: &SourceControlSnapshot) -> bool {
    !snapshot.branch.is_empty()
        || snapshot.ahead > 0
        || snapshot.behind > 0
        || !snapshot.files.is_empty()
        || snapshot.added_lines.is_some()
        || snapshot.removed_lines.is_some()
}

fn source_control_branch_line(snapshot: &SourceControlSnapshot) -> Option<String> {
    if snapshot.branch.is_empty() {
        return None;
    }

    let mut branch_line = snapshot.branch.clone();
    if snapshot.ahead > 0 || snapshot.behind > 0 {
        branch_line.push_str(&format!(
            "  ahead:{} behind:{}",
            snapshot.ahead, snapshot.behind
        ));
    }
    Some(branch_line)
}

fn merge_source_control_refresh_result(
    current: Option<&SourceControlSnapshot>,
    incoming: SourceControlSnapshot,
) -> SourceControlSnapshot {
    if incoming.last_error.is_none() {
        return incoming;
    }

    match current {
        Some(current) if source_control_snapshot_has_display_data(current) => {
            let mut merged = current.clone();
            merged.loading = incoming.loading;
            merged.last_error = incoming.last_error;
            merged.partial_warning = incoming.partial_warning;
            merged
        }
        _ => incoming,
    }
}

fn terminal_manager_diff_summary_model(
    snapshot: Option<&SourceControlSnapshot>,
) -> TerminalManagerDiffSummaryModel {
    match snapshot {
        Some(snapshot) => match (snapshot.added_lines, snapshot.removed_lines) {
            (Some(added_lines), Some(removed_lines)) => TerminalManagerDiffSummaryModel {
                state: TerminalManagerDiffSummaryState::Ready,
                added_lines,
                removed_lines,
                tooltip_lines: source_control_tooltip_lines(
                    snapshot,
                    SOURCE_CONTROL_TOOLTIP_FILE_LIMIT,
                ),
            },
            _ if snapshot.loading => TerminalManagerDiffSummaryModel {
                state: TerminalManagerDiffSummaryState::Loading,
                added_lines: 0,
                removed_lines: 0,
                tooltip_lines: source_control_tooltip_lines(
                    snapshot,
                    SOURCE_CONTROL_TOOLTIP_FILE_LIMIT,
                ),
            },
            _ if snapshot.last_error.is_some() => TerminalManagerDiffSummaryModel {
                state: TerminalManagerDiffSummaryState::Error,
                added_lines: 0,
                removed_lines: 0,
                tooltip_lines: source_control_tooltip_lines(
                    snapshot,
                    SOURCE_CONTROL_TOOLTIP_FILE_LIMIT,
                ),
            },
            _ => TerminalManagerDiffSummaryModel {
                state: TerminalManagerDiffSummaryState::Unknown,
                added_lines: 0,
                removed_lines: 0,
                tooltip_lines: source_control_tooltip_lines(
                    snapshot,
                    SOURCE_CONTROL_TOOLTIP_FILE_LIMIT,
                ),
            },
        },
        None => TerminalManagerDiffSummaryModel {
            state: TerminalManagerDiffSummaryState::Unknown,
            added_lines: 0,
            removed_lines: 0,
            tooltip_lines: vec!["Status pending".to_owned()],
        },
    }
}

#[allow(dead_code)]
fn terminal_manager_diff_summary_visual(
    summary: &TerminalManagerDiffSummaryModel,
) -> TerminalManagerDiffSummaryVisual {
    match summary.state {
        TerminalManagerDiffSummaryState::Ready => {
            // When there are no changes at all, show nothing instead of "+0 -0"
            if summary.added_lines == 0 && summary.removed_lines == 0 {
                TerminalManagerDiffSummaryVisual::Placeholder {
                    text: "",
                    color: Color32::TRANSPARENT,
                }
            } else {
                TerminalManagerDiffSummaryVisual::Totals {
                    added_text: format!("+{}", summary.added_lines),
                    removed_text: format!("-{}", summary.removed_lines),
                    added_color: source_control_badge_color(SourceControlBadgeState::Clean),
                    removed_color: source_control_badge_color(SourceControlBadgeState::Error),
                    separator_color: TEXT_MUTED,
                }
            }
        }
        TerminalManagerDiffSummaryState::Loading => TerminalManagerDiffSummaryVisual::Placeholder {
            text: "...",
            color: TEXT_MUTED,
        },
        TerminalManagerDiffSummaryState::Unknown | TerminalManagerDiffSummaryState::Error => {
            TerminalManagerDiffSummaryVisual::Placeholder {
                text: "--",
                color: TEXT_MUTED,
            }
        }
    }
}

fn source_control_tooltip_lines(snapshot: &SourceControlSnapshot, max_files: usize) -> Vec<String> {
    let has_display_data = source_control_snapshot_has_display_data(snapshot);
    let mut lines = Vec::with_capacity(max_files.saturating_add(4));

    if snapshot.loading {
        lines.push("Refreshing source control...".to_owned());
    }
    if let Some(error) = &snapshot.last_error {
        lines.push(error.clone());
    }
    if let Some(warning) = &snapshot.partial_warning {
        lines.push(warning.clone());
    }
    if !has_display_data {
        if lines.is_empty() {
            lines.push("Status pending".to_owned());
        }
        return lines;
    }

    if let Some(branch_line) = source_control_branch_line(snapshot) {
        lines.push(branch_line);
    }

    if snapshot.files.is_empty() {
        if snapshot.last_error.is_none() && !snapshot.loading {
            lines.push("Working tree is clean".to_owned());
        }
        return lines;
    }

    for file in snapshot.files.iter().take(max_files) {
        let staged = if file.staged { " [staged]" } else { "" };
        lines.push(format!("{}{}: {}", file.status, staged, file.path));
    }

    let remaining_files = snapshot
        .files
        .len()
        .saturating_sub(max_files)
        .saturating_add(snapshot.omitted_files);
    if remaining_files > 0 {
        lines.push(format!("+{} more", remaining_files));
    }

    lines
}

#[allow(dead_code)]
fn terminal_manager_diff_summary_layout_job(
    ui: &Ui,
    summary: &TerminalManagerDiffSummaryModel,
) -> LayoutJob {
    let visual = terminal_manager_diff_summary_visual(summary);
    let mut layout_job = LayoutJob::default();
    layout_job.wrap.max_width = f32::INFINITY;
    let font_id = egui::TextStyle::Small.resolve(ui.style());

    match visual {
        TerminalManagerDiffSummaryVisual::Totals {
            added_text,
            removed_text,
            added_color,
            removed_color,
            separator_color,
        } => {
            layout_job.append(
                &added_text,
                0.0,
                TextFormat {
                    font_id: font_id.clone(),
                    color: added_color,
                    ..TextFormat::default()
                },
            );
            layout_job.append(
                " ",
                0.0,
                TextFormat {
                    font_id: font_id.clone(),
                    color: separator_color,
                    ..TextFormat::default()
                },
            );
            layout_job.append(
                &removed_text,
                0.0,
                TextFormat {
                    font_id,
                    color: removed_color,
                    ..TextFormat::default()
                },
            );
        }
        TerminalManagerDiffSummaryVisual::Placeholder { text, color } => {
            layout_job.append(
                text,
                0.0,
                TextFormat {
                    font_id,
                    color,
                    ..TextFormat::default()
                },
            );
        }
    }

    layout_job
}

#[allow(dead_code)]
fn draw_terminal_manager_diff_summary(
    ui: &mut Ui,
    summary: &TerminalManagerDiffSummaryModel,
) -> egui::Response {
    let response = ui.add(
        egui::Label::new(WidgetText::from(terminal_manager_diff_summary_layout_job(
            ui, summary,
        )))
        .sense(Sense::hover()),
    );

    // Hover tooltip removed per design decision
    response
}

fn draw_terminal_manager_title_and_diff_summary(
    ui: &mut Ui,
    title: &str,
    text_color: Color32,
    is_active: bool,
    row_height: f32,
    #[allow(unused_variables)] diff_summary: &TerminalManagerDiffSummaryModel,
    show_pointing_cursor: bool,
    tooltip_text: Option<&str>,
) -> TerminalManagerTitleSummaryLayout {
    ui.allocate_ui_with_layout(
        egui::vec2(ui.available_width().max(0.0), row_height),
        Layout::left_to_right(Align::Center),
        |ui| {
            let font_id = egui::TextStyle::Body.resolve(ui.style());
            let title_label = egui::Label::new(RichText::new(title).color(text_color).strong())
                .truncate()
                .selectable(false)
                .sense(Sense::hover());
            let title_response = ui.add(title_label);
            {
                let info = WidgetInfo::selected(
                    WidgetType::SelectableLabel,
                    ui.is_enabled(),
                    is_active,
                    title,
                );
                title_response.widget_info(|| info.clone());
            }
            let title_response = if show_pointing_cursor {
                title_response.on_hover_cursor(egui::CursorIcon::PointingHand)
            } else {
                title_response
            };
            #[cfg(test)]
            let title_response = if let Some(tooltip) = tooltip_text {
                with_truncation_tooltip(
                    ui,
                    title_response,
                    tooltip,
                    &font_id,
                    text_color,
                    ui.available_width(),
                )
            } else {
                title_response.on_hover_text(title)
            };
            #[cfg(not(test))]
            let _title_response = if let Some(tooltip) = tooltip_text {
                with_truncation_tooltip(
                    ui,
                    title_response,
                    tooltip,
                    &font_id,
                    text_color,
                    ui.available_width(),
                )
            } else {
                title_response.on_hover_text(title)
            };

            ui.add_space(6.0);

            // Always render diff summary; bind response only in test builds for rect measurement
            #[cfg(test)]
            let diff_summary_response = draw_terminal_manager_diff_summary(ui, diff_summary);
            #[cfg(not(test))]
            let _ = draw_terminal_manager_diff_summary(ui, diff_summary);

            TerminalManagerTitleSummaryLayout {
                #[cfg(test)]
                title_rect: title_response.rect,
                #[cfg(test)]
                diff_summary_rect: diff_summary_response.rect,
            }
        },
    )
    .inner
}

fn paint_minimal_combo_icon(
    ui: &Ui,
    rect: egui::Rect,
    visuals: &egui::style::WidgetVisuals,
    is_open: bool,
    _above_or_below: egui::AboveOrBelow,
) {
    let center = rect.center();
    let stroke = Stroke::new(1.6, visuals.fg_stroke.color);
    let top = if is_open {
        egui::pos2(center.x - 4.0, center.y + 1.5)
    } else {
        egui::pos2(center.x - 4.0, center.y - 1.5)
    };
    let mid = if is_open {
        egui::pos2(center.x, center.y - 2.5)
    } else {
        egui::pos2(center.x, center.y + 2.5)
    };
    let bottom = if is_open {
        egui::pos2(center.x + 4.0, center.y + 1.5)
    } else {
        egui::pos2(center.x + 4.0, center.y - 1.5)
    };

    ui.painter().line_segment([top, mid], stroke);
    ui.painter().line_segment([mid, bottom], stroke);
}

fn with_minimal_button_chrome<R>(ui: &mut Ui, add_contents: impl FnOnce(&mut Ui) -> R) -> R {
    ui.scope(|ui| {
        let style = ui.style_mut();
        style.spacing.button_padding = egui::vec2(8.0, 5.0);
        let hover_fill = with_alpha(BTN_ICON_HOVER, 110);

        style.visuals.widgets.inactive.bg_fill = Color32::TRANSPARENT;
        style.visuals.widgets.inactive.weak_bg_fill = Color32::TRANSPARENT;
        style.visuals.widgets.inactive.bg_stroke = Stroke::NONE;
        style.visuals.widgets.inactive.fg_stroke = Stroke::new(1.0, with_alpha(TEXT_PRIMARY, 190));

        style.visuals.widgets.hovered.bg_fill = hover_fill;
        style.visuals.widgets.hovered.weak_bg_fill = hover_fill;
        style.visuals.widgets.hovered.bg_stroke = Stroke::NONE;
        style.visuals.widgets.hovered.fg_stroke =
            Stroke::new(1.0, Color32::from_rgb(255, 255, 255));

        style.visuals.widgets.active.bg_fill = Color32::TRANSPARENT;
        style.visuals.widgets.active.weak_bg_fill = Color32::TRANSPARENT;
        style.visuals.widgets.active.bg_stroke = Stroke::NONE;
        style.visuals.widgets.active.fg_stroke = Stroke::new(1.0, Color32::from_rgb(255, 255, 255));

        style.visuals.widgets.open.bg_fill = Color32::TRANSPARENT;
        style.visuals.widgets.open.weak_bg_fill = Color32::TRANSPARENT;
        style.visuals.widgets.open.bg_stroke = Stroke::NONE;
        style.visuals.widgets.open.fg_stroke = Stroke::new(1.0, Color32::from_rgb(255, 255, 255));

        add_contents(ui)
    })
    .inner
}

fn draw_terminal_saved_message_menu_button(
    ui: &mut Ui,
    saved_messages: &[String],
    send_message: &mut Option<String>,
) -> egui::Response {
    let message_menu = with_minimal_button_chrome(ui, |ui| {
        ui.menu_button(format!("{}", icons::CHAT_TEXT), |ui| {
            with_minimal_button_chrome(ui, |ui| {
                if saved_messages.is_empty() {
                    ui.label(RichText::new("No saved messages").color(TEXT_MUTED));
                    return;
                }

                for message in saved_messages {
                    if ui.button(message).clicked() {
                        *send_message = Some(message.clone());
                        ui.close_menu();
                    }
                }
            });
        })
    });
    let response = message_menu
        .response
        .on_hover_text("Send saved message")
        .on_hover_cursor(egui::CursorIcon::PointingHand);
    if response.hovered() {
        ui.ctx().set_cursor_icon(egui::CursorIcon::PointingHand);
    }
    response
}

fn project_group_header_actions_width(_section_gap: f32) -> f32 {
    CONTROL_ROW_HEIGHT
}

fn project_group_header_action_spec(
    action_kind: TerminalKind,
) -> (AppIcon, Color32, Color32, &'static str) {
    match action_kind {
        TerminalKind::Foreground => (
            icons::TERMINAL,
            BTN_BLUE,
            BTN_BLUE_HOVER,
            "Open Foreground Launcher",
        ),
        TerminalKind::Background => (
            icons::LIST,
            BTN_TEAL,
            BTN_TEAL_HOVER,
            "New Background Terminal",
        ),
    }
}

fn terminal_manager_filter_label(filter: TerminalManagerFilter) -> &'static str {
    match filter {
        TerminalManagerFilter::Foreground => "Foreground",
        TerminalManagerFilter::Background => "Background",
    }
}

fn terminal_manager_filter_color(filter: TerminalManagerFilter) -> Color32 {
    match filter {
        TerminalManagerFilter::Foreground => ACCENT,
        TerminalManagerFilter::Background => TEXT_MUTED,
    }
}

fn terminal_manager_filter_row_height(base_height: f32) -> f32 {
    base_height + TERMINAL_MANAGER_FILTER_ROW_HEIGHT_EXTRA
}

#[derive(Clone, Copy, Debug)]
struct TerminalManagerFilterLayout {
    foreground_slot_rect: egui::Rect,
    background_slot_rect: egui::Rect,
    foreground_label_rect: egui::Rect,
    background_label_rect: egui::Rect,
}

fn terminal_manager_filter_label_size(ui: &Ui, filter: TerminalManagerFilter) -> Vec2 {
    WidgetText::from(RichText::new(terminal_manager_filter_label(filter)).strong())
        .into_galley(
            ui,
            Some(TextWrapMode::Truncate),
            f32::INFINITY,
            egui::TextStyle::Body,
        )
        .size()
}

fn terminal_manager_filter_label_rect(slot_rect: egui::Rect, label_size: Vec2) -> egui::Rect {
    let label_width = label_size.x.min(slot_rect.width().max(0.0));
    let label_x = slot_rect.center().x - (label_width * 0.5);

    egui::Rect::from_min_size(
        egui::pos2(
            label_x,
            slot_rect.top() + TERMINAL_MANAGER_FILTER_TOP_PADDING,
        ),
        egui::vec2(label_width, label_size.y),
    )
}

fn terminal_manager_filter_slot_rects(row_rect: egui::Rect) -> (egui::Rect, egui::Rect) {
    let inner_left = row_rect.left() + TERMINAL_MANAGER_FILTER_SIDE_PADDING;
    let inner_right = (row_rect.right() - TERMINAL_MANAGER_FILTER_SIDE_PADDING).max(inner_left);
    let inner_width = (inner_right - inner_left).max(0.0);
    let center_gap = TERMINAL_MANAGER_FILTER_CENTER_GAP.min(inner_width);
    let slot_width = ((inner_width - center_gap).max(0.0)) * 0.5;

    let foreground_slot_rect = egui::Rect::from_min_max(
        egui::pos2(inner_left, row_rect.top()),
        egui::pos2(inner_left + slot_width, row_rect.bottom()),
    );
    let background_slot_rect = egui::Rect::from_min_max(
        egui::pos2(foreground_slot_rect.right() + center_gap, row_rect.top()),
        egui::pos2(inner_right, row_rect.bottom()),
    );

    (foreground_slot_rect, background_slot_rect)
}

fn terminal_manager_filter_layout(
    row_rect: egui::Rect,
    foreground_label_size: Vec2,
    background_label_size: Vec2,
) -> TerminalManagerFilterLayout {
    let (foreground_slot_rect, background_slot_rect) = terminal_manager_filter_slot_rects(row_rect);

    TerminalManagerFilterLayout {
        foreground_slot_rect,
        background_slot_rect,
        foreground_label_rect: terminal_manager_filter_label_rect(
            foreground_slot_rect,
            foreground_label_size,
        ),
        background_label_rect: terminal_manager_filter_label_rect(
            background_slot_rect,
            background_label_size,
        ),
    }
}

fn terminal_manager_filter_underline_rect(label_rect: egui::Rect) -> egui::Rect {
    egui::Rect::from_min_max(
        egui::pos2(
            label_rect.left(),
            label_rect.bottom() + TERMINAL_MANAGER_FILTER_UNDERLINE_GAP,
        ),
        egui::pos2(
            label_rect.right(),
            label_rect.bottom()
                + TERMINAL_MANAGER_FILTER_UNDERLINE_GAP
                + TERMINAL_MANAGER_FILTER_UNDERLINE_HEIGHT,
        ),
    )
}

fn draw_terminal_manager_filter_tabs(
    ui: &mut Ui,
    selected_filter: &mut TerminalManagerFilter,
) -> bool {
    let mut changed = false;

    let row_size = egui::vec2(
        ui.available_width(),
        terminal_manager_filter_row_height(ui.spacing().interact_size.y),
    );
    let (row_rect, _) = ui.allocate_exact_size(row_size, Sense::hover());
    let layout = terminal_manager_filter_layout(
        row_rect,
        terminal_manager_filter_label_size(ui, TerminalManagerFilter::Foreground),
        terminal_manager_filter_label_size(ui, TerminalManagerFilter::Background),
    );

    for (filter, slot_rect, label_rect) in [
        (
            TerminalManagerFilter::Foreground,
            layout.foreground_slot_rect,
            layout.foreground_label_rect,
        ),
        (
            TerminalManagerFilter::Background,
            layout.background_slot_rect,
            layout.background_label_rect,
        ),
    ] {
        let is_selected = *selected_filter == filter;
        let slot_response = ui.interact(
            slot_rect,
            ui.make_persistent_id((
                "terminal-manager-filter-slot",
                terminal_manager_filter_label(filter),
            )),
            Sense::click(),
        );

        let label_response = ui.put(
            label_rect,
            egui::Label::new(
                RichText::new(terminal_manager_filter_label(filter))
                    .strong()
                    .color(if is_selected {
                        terminal_manager_filter_color(filter)
                    } else {
                        with_alpha(TEXT_MUTED, 180)
                    }),
            )
            .truncate()
            .selectable(false)
            .sense(Sense::click()),
        );

        let response = slot_response
            .union(label_response)
            .on_hover_cursor(egui::CursorIcon::PointingHand);

        if is_selected {
            ui.painter().rect_filled(
                terminal_manager_filter_underline_rect(label_rect),
                2.0,
                terminal_manager_filter_color(filter),
            );
        }

        if response.clicked() && !is_selected {
            *selected_filter = filter;
            changed = true;
        }
    }

    changed
}

fn draw_input_history_filter_tabs(ui: &mut Ui, selected_filter: &mut InputHistoryFilter) -> bool {
    let mut changed = false;
    let available_width = ui.available_width();
    let gap = 8.0;
    let tab_count = 3.0;
    let tab_width = ((available_width - gap * (tab_count - 1.0)) / tab_count).max(40.0);

    ui.horizontal(|ui| {
        ui.spacing_mut().item_spacing.x = gap;
        for filter in [
            InputHistoryFilter::All,
            InputHistoryFilter::Foreground,
            InputHistoryFilter::Background,
        ] {
            let is_selected = *selected_filter == filter;
            let text = filter.label();
            let (rect, response) =
                ui.allocate_exact_size(egui::vec2(tab_width, CONTROL_ROW_HEIGHT), Sense::click());
            let response = response.on_hover_cursor(egui::CursorIcon::PointingHand);

            // Background for selected tab
            if is_selected {
                ui.painter().rect_filled(rect.shrink(1.0), 6.0, BTN_ICON);
            } else if response.hovered() {
                ui.painter()
                    .rect_filled(rect.shrink(1.0), 6.0, with_alpha(BTN_ICON_HOVER, 80));
            }

            // Text
            ui.painter().text(
                rect.center(),
                egui::Align2::CENTER_CENTER,
                text,
                egui::FontId::proportional(13.0),
                if is_selected {
                    TEXT_PRIMARY
                } else {
                    TEXT_MUTED
                },
            );

            if response.clicked() && !is_selected {
                *selected_filter = filter;
                changed = true;
            }
        }
    });

    changed
}

fn format_relative_time(timestamp: u64) -> String {
    let now = SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .map(|d| d.as_secs())
        .unwrap_or(0);
    let diff = now.saturating_sub(timestamp);

    if diff < 60 {
        "just now".to_owned()
    } else if diff < 3600 {
        format!("{}m ago", diff / 60)
    } else if diff < 86400 {
        format!("{}h ago", diff / 3600)
    } else if diff < 604800 {
        format!("{}d ago", diff / 86400)
    } else if diff < 2592000 {
        format!("{}w ago", diff / 604800)
    } else {
        format!("{}mo ago", diff / 2592000)
    }
}

fn terminal_ids_for_project_kind(
    terminals: &BTreeMap<u64, TerminalEntry>,
    project_id: u64,
    kind: TerminalKind,
) -> Vec<u64> {
    terminals
        .iter()
        .filter(|(_, terminal)| terminal.project_id == project_id && terminal.kind == kind)
        .map(|(id, _)| *id)
        .collect()
}

fn project_group_header_row_layout(total_width: f32, section_gap: f32) -> (f32, f32) {
    let total_width = total_width.max(0.0);
    let section_gap = section_gap.max(0.0);
    let actions_width = project_group_header_actions_width(section_gap).min(total_width);
    let label_width = (total_width - actions_width - section_gap).max(0.0);
    (label_width, actions_width)
}

fn draw_project_group_header(
    app: &mut AdeApp,
    ui: &mut Ui,
    project_name: &str,
    open: bool,
    can_expand: bool,
    action_kind: TerminalKind,
    foreground_launchers: &[LauncherEntry],
    diff_summary: &TerminalManagerDiffSummaryModel,
    has_live_terminal: bool,
) -> (egui::Response, bool, Option<String>, bool) {
    let row_width = ui.available_width();
    let section_gap = ui.spacing().item_spacing.x;
    let (_label_width, actions_width) = project_group_header_row_layout(row_width, section_gap);
    let row_height = CONTROL_ROW_HEIGHT;

    // Allocate the full row for visual layout, but we'll create separate interactions
    let (_, row_rect) = ui.allocate_space(egui::vec2(row_width, row_height));

    // Calculate action buttons rect
    let actions_rect = egui::Rect::from_min_size(
        egui::pos2(row_rect.right() - actions_width, row_rect.top()),
        egui::vec2(actions_width, row_height),
    );
    let _action_hover_response = ui
        .interact(
            actions_rect,
            ui.id().with(("project_group_action", project_name)),
            Sense::hover(),
        )
        .on_hover_cursor(egui::CursorIcon::PointingHand);

    // Create interaction area for the non-button portion of the row (for click)
    let body_rect = egui::Rect::from_min_size(
        row_rect.min,
        egui::vec2(row_width - actions_width, row_height),
    );

    let body_response = ui.interact(
        body_rect,
        ui.id().with(("project_group_body", project_name)),
        Sense::click(),
    );

    // Set hover cursor based on expandability
    let body_response = if can_expand {
        body_response.on_hover_cursor(egui::CursorIcon::PointingHand)
    } else {
        body_response
    };

    // Project header is bright only when it has at least one live (non-exited) terminal.
    // When all terminals are closed/exited, the project header dims back to muted color.
    let text_color = if has_live_terminal {
        TEXT_PRIMARY
    } else if body_response.hovered() {
        with_alpha(TEXT_MUTED, 180)
    } else {
        with_alpha(TEXT_MUTED, 180)
    };

    let mut spawn_clicked = false;
    let mut selected_launcher_id = None;

    // Draw label content
    let label_rect = egui::Rect::from_min_size(
        body_rect.min,
        egui::vec2(body_rect.width().max(0.0), row_height),
    );
    if label_rect.width() > 0.0 && ui.is_rect_visible(label_rect) {
        ui.scope_builder(
            egui::UiBuilder::new()
                .max_rect(label_rect)
                .layout(Layout::left_to_right(Align::Center)),
            |ui| {
                let label = project_name.to_string();
                let _ = draw_terminal_manager_title_and_diff_summary(
                    ui,
                    &label,
                    text_color,
                    open,
                    row_height,
                    diff_summary,
                    can_expand,
                    Some(project_name),
                );
            },
        );
    }

    // Draw action buttons in separate scope
    ui.scope_builder(
        egui::UiBuilder::new()
            .max_rect(actions_rect)
            .layout(Layout::right_to_left(Align::Center)),
        |ui| {
            let (icon, bg, hover_bg, tooltip) = project_group_header_action_spec(action_kind);
            if action_kind == TerminalKind::Foreground {
                selected_launcher_id = styled_launcher_menu_button(
                    app,
                    ui,
                    icon,
                    bg,
                    hover_bg,
                    BTN_ICON_ACTIVE,
                    tooltip,
                    foreground_launchers,
                );
            } else if styled_icon_button(ui, icon, bg, hover_bg, BTN_ICON_ACTIVE, tooltip) {
                spawn_clicked = true;
            }
        },
    );

    // Determine header click - only if body was clicked and no action was taken
    let header_clicked =
        body_response.clicked() && !spawn_clicked && selected_launcher_id.is_none();

    (
        body_response,
        spawn_clicked,
        selected_launcher_id,
        header_clicked,
    )
}

fn styled_icon_button(
    ui: &mut Ui,
    icon: AppIcon,
    _bg: Color32,
    _hover_bg: Color32,
    _active_bg: Color32,
    tooltip: &str,
) -> bool {
    let (rect, response) = ui.allocate_exact_size(
        egui::vec2(CONTROL_ROW_HEIGHT, CONTROL_ROW_HEIGHT),
        Sense::click(),
    );
    let response = response
        .on_hover_text(tooltip)
        .on_hover_cursor(egui::CursorIcon::PointingHand);

    if response.hovered() {
        ui.painter()
            .rect_filled(rect.shrink(1.0), 8.0, with_alpha(BTN_ICON_HOVER, 110));
    }

    let icon_color = if response.is_pointer_button_down_on() || response.hovered() {
        Color32::from_rgb(255, 255, 255)
    } else {
        with_alpha(TEXT_PRIMARY, 178)
    };
    ui.painter().text(
        rect.center(),
        egui::Align2::CENTER_CENTER,
        format!("{icon}"),
        egui::FontId::proportional(15.0),
        icon_color,
    );

    response.clicked()
}

/// Draws an icon button specifically for the editor header with high contrast.
/// Unlike `styled_icon_button`, this helper always shows a visible background
/// and uses high-contrast colors suitable for dark surfaces.
fn editor_header_icon_button(
    ui: &mut Ui,
    icon: AppIcon,
    bg: Color32,
    hover_bg: Color32,
    icon_color: Color32,
    tooltip: &str,
) -> bool {
    let (rect, response) = ui.allocate_exact_size(
        egui::vec2(CONTROL_ROW_HEIGHT, CONTROL_ROW_HEIGHT),
        Sense::click(),
    );
    let response = response
        .on_hover_text(tooltip)
        .on_hover_cursor(egui::CursorIcon::PointingHand);

    // Always show a visible background (not transparent when inactive)
    let bg_color = if response.hovered() {
        hover_bg
    } else {
        bg
    };
    ui.painter().rect_filled(rect.shrink(2.0), 6.0, bg_color);

    // Icon color: use provided high-contrast color
    let final_icon_color = if response.is_pointer_button_down_on() {
        Color32::from_rgb(255, 255, 255)
    } else {
        icon_color
    };
    ui.painter().text(
        rect.center(),
        egui::Align2::CENTER_CENTER,
        format!("{icon}"),
        egui::FontId::proportional(15.0),
        final_icon_color,
    );

    response.clicked()
}

/// Draws the terminal manager test-done toggle button.
/// - When `test_done` is true: icon is green (100, 200, 100)
/// - When `test_done` is false: icon is white (TEXT_PRIMARY)
/// Hover adds a subtle background highlight but does not alter icon color.
fn terminal_manager_test_done_toggle(ui: &mut Ui, test_done: bool) -> bool {
    let (rect, response) = ui.allocate_exact_size(
        egui::vec2(CONTROL_ROW_HEIGHT, CONTROL_ROW_HEIGHT),
        Sense::click(),
    );
    let tooltip = if test_done {
        "Added to Check-list - click to remove"
    } else {
        "Add to Check-list"
    };
    let response = response
        .on_hover_text(tooltip)
        .on_hover_cursor(egui::CursorIcon::PointingHand);

    // Hover background highlight (subtle)
    if response.hovered() {
        let hover_alpha = if test_done { 80 } else { 60 };
        ui.painter().rect_filled(
            rect.shrink(1.0),
            8.0,
            with_alpha(BTN_ICON_HOVER, hover_alpha),
        );
    }

    // Icon color: green when done, white when not done
    let icon_color = if test_done {
        Color32::from_rgb(100, 200, 100)
    } else {
        TEXT_PRIMARY
    };

    ui.painter().text(
        rect.center(),
        egui::Align2::CENTER_CENTER,
        format!("{}", icons::CHECK_CIRCLE),
        egui::FontId::proportional(15.0),
        icon_color,
    );

    response.clicked()
}

fn styled_launcher_menu_button(
    app: &mut AdeApp,
    ui: &mut Ui,
    icon: AppIcon,
    _bg: Color32,
    _hover_bg: Color32,
    _active_bg: Color32,
    tooltip: &str,
    launchers: &[LauncherEntry],
) -> Option<String> {
    let mut selected_launcher = None;
    let (slot_rect, slot_response) = ui.allocate_exact_size(
        egui::vec2(CONTROL_ROW_HEIGHT, CONTROL_ROW_HEIGHT),
        Sense::hover(),
    );
    let slot_response = slot_response.on_hover_cursor(egui::CursorIcon::PointingHand);
    let menu = ui
        .scope_builder(
            egui::UiBuilder::new()
                .max_rect(slot_rect)
                .layout(Layout::centered_and_justified(egui::Direction::LeftToRight)),
            |ui| {
                with_minimal_button_chrome(ui, |ui| {
                    ui.menu_button(format!("{icon}"), |ui| {
                        with_minimal_button_chrome(ui, |ui| {
                            if launchers.is_empty() {
                                ui.label(
                                    RichText::new("Enable a launcher in Settings > Launchers")
                                        .small()
                                        .color(TEXT_MUTED),
                                );
                                return;
                            }

                            for launcher in launchers {
                                let response = ui.horizontal(|ui| {
                                    let _ = app.draw_launcher_icon(ui, launcher.icon_key, 20.0);
                                    ui.add_space(6.0);
                                    ui.vertical(|ui| {
                                        ui.add(
                                            egui::Label::new(
                                                RichText::new(&launcher.display_name)
                                                    .strong()
                                                    .color(TEXT_PRIMARY),
                                            )
                                            .selectable(false),
                                        );
                                        ui.add(
                                            egui::Label::new(
                                                RichText::new(&launcher.launch_command)
                                                    .small()
                                                    .color(TEXT_MUTED),
                                            )
                                            .selectable(false),
                                        );
                                    });
                                });
                                let row_id =
                                    ui.make_persistent_id(("foreground-launcher", &launcher.id));
                                let row_response = ui
                                    .interact(response.response.rect, row_id, Sense::click())
                                    .on_hover_cursor(egui::CursorIcon::PointingHand);
                                if row_response.hovered() {
                                    ui.ctx().set_cursor_icon(egui::CursorIcon::PointingHand);
                                }
                                if row_response.clicked() {
                                    selected_launcher = Some(launcher.id.clone());
                                    ui.close_menu();
                                }
                            }
                        });
                    })
                })
            },
        )
        .inner;

    let response = menu
        .response
        .on_hover_text(if launchers.is_empty() {
            "No foreground launchers enabled"
        } else {
            tooltip
        })
        .on_hover_cursor(egui::CursorIcon::PointingHand)
        .union(slot_response);

    if response.hovered() {
        ui.ctx().set_cursor_icon(egui::CursorIcon::PointingHand);
    }

    selected_launcher
}

fn activity_rail_icon_button(
    ui: &mut Ui,
    selected: bool,
    icon: AppIcon,
    tooltip: &str,
) -> egui::Response {
    let (rect, response) = ui.allocate_exact_size(
        egui::vec2(CONTROL_ROW_HEIGHT, CONTROL_ROW_HEIGHT),
        Sense::click(),
    );
    let response = response
        .on_hover_text(tooltip)
        .on_hover_cursor(egui::CursorIcon::PointingHand);

    if response.hovered() {
        ui.painter()
            .rect_filled(rect.shrink(1.0), 8.0, with_alpha(BTN_ICON_HOVER, 110));
    }

    let icon_color = if selected || response.hovered() || response.is_pointer_button_down_on() {
        Color32::from_rgb(255, 255, 255)
    } else {
        with_alpha(TEXT_PRIMARY, 170)
    };
    ui.painter().text(
        rect.center(),
        egui::Align2::CENTER_CENTER,
        format!("{icon}"),
        egui::FontId::proportional(14.0),
        icon_color,
    );

    response
}

fn paint_activity_rail_warning_badge(ui: &Ui, button_rect: egui::Rect) {
    let center = egui::pos2(button_rect.right() - 6.0, button_rect.top() + 6.0);
    ui.painter()
        .circle_filled(center, 4.0, Color32::from_rgb(232, 184, 76));
    ui.painter()
        .circle_stroke(center, 4.0, Stroke::new(1.0, SURFACE_BG));
}

fn styled_icon_toggle(ui: &mut Ui, selected: bool, icon: AppIcon, tooltip: &str) -> bool {
    activity_rail_icon_button(ui, selected, icon, tooltip).clicked()
}

fn settings_surface_frame(fill: Color32, margin: f32) -> egui::Frame {
    egui::Frame::none()
        .fill(fill)
        .stroke(Stroke::new(1.0, BORDER_COLOR))
        .rounding(12.0)
        .inner_margin(egui::Margin::same(margin))
}

fn settings_window_size_for_screen(screen_size: Vec2, window_margin: egui::Margin) -> Vec2 {
    let safe_screen_size = (screen_size
        - egui::vec2(SETTINGS_WINDOW_SCREEN_MARGIN, SETTINGS_WINDOW_SCREEN_MARGIN)
        - window_margin.sum())
    .max(egui::Vec2::ZERO);
    egui::vec2(
        SETTINGS_WINDOW_DEFAULT_WIDTH.min(safe_screen_size.x),
        SETTINGS_WINDOW_DEFAULT_HEIGHT.min(safe_screen_size.y),
    )
}

fn settings_popup_uses_stacked_layout(available_width: f32) -> bool {
    available_width < SETTINGS_WINDOW_STACK_BREAKPOINT
}

fn settings_diagnostics_uses_single_column(available_width: f32) -> bool {
    available_width < SETTINGS_DIAGNOSTICS_SINGLE_COLUMN_BREAKPOINT
}

fn settings_saved_messages_stacks_draft_row(available_width: f32) -> bool {
    available_width < SETTINGS_SAVED_MESSAGES_COMPACT_BREAKPOINT
}

fn settings_saved_messages_project_header_layout(
    row_rect: egui::Rect,
    disclosure_width: f32,
    count_width: f32,
    section_gap: f32,
) -> SettingsSavedMessagesProjectHeaderLayout {
    let safe_disclosure_width = disclosure_width.clamp(0.0, row_rect.width());
    let remaining_width = (row_rect.width() - safe_disclosure_width).max(0.0);
    let safe_count_width = count_width.clamp(0.0, remaining_width);
    let count_gap = if safe_count_width > 0.0 {
        section_gap.min((remaining_width - safe_count_width).max(0.0))
    } else {
        0.0
    };
    let content_width = (remaining_width - safe_count_width - count_gap).max(0.0);
    let disclosure_rect = egui::Rect::from_min_size(
        row_rect.min,
        egui::vec2(safe_disclosure_width, row_rect.height()),
    );
    let icon_width = CONTROL_ROW_HEIGHT.min(content_width);
    let icon_gap = SETTINGS_ACCORDION_HEADER_ICON_GAP.min((content_width - icon_width).max(0.0));
    let title_width = (content_width - icon_width - icon_gap).max(0.0);
    let content_rect = egui::Rect::from_min_size(
        egui::pos2(disclosure_rect.right(), row_rect.top()),
        egui::vec2(content_width, row_rect.height()),
    );
    let folder_icon_rect = egui::Rect::from_min_size(
        content_rect.min,
        egui::vec2(icon_width, content_rect.height()),
    );
    let title_rect = egui::Rect::from_min_size(
        egui::pos2(folder_icon_rect.right() + icon_gap, content_rect.top()),
        egui::vec2(title_width, content_rect.height()),
    );
    let count_rect = egui::Rect::from_min_size(
        egui::pos2(content_rect.right() + count_gap, row_rect.top()),
        egui::vec2(safe_count_width, row_rect.height()),
    );

    SettingsSavedMessagesProjectHeaderLayout {
        disclosure_rect,
        folder_icon_rect,
        title_rect,
        count_rect,
    }
}

fn settings_accordion_disclosure_icon_rect(disclosure_rect: egui::Rect) -> egui::Rect {
    let icon_size = disclosure_rect
        .width()
        .min(disclosure_rect.height())
        .min(10.0);
    egui::Rect::from_center_size(
        egui::pos2(
            disclosure_rect.center().x,
            disclosure_rect.center().y + SETTINGS_ACCORDION_DISCLOSURE_Y_OFFSET,
        ),
        egui::vec2(icon_size, icon_size),
    )
}

fn paint_settings_accordion_disclosure_icon(
    ui: &mut Ui,
    disclosure_rect: egui::Rect,
    openness: f32,
    response: &egui::Response,
) {
    let visuals = ui.style().interact(response);
    let rect = settings_accordion_disclosure_icon_rect(disclosure_rect);
    let rect = egui::Rect::from_center_size(rect.center(), rect.size() * 0.75);
    let rect = rect.expand(visuals.expansion);
    let mut points = vec![rect.left_top(), rect.right_top(), rect.center_bottom()];
    let rotation = egui::emath::Rot2::from_angle(egui::remap(
        openness,
        0.0..=1.0,
        -std::f32::consts::FRAC_PI_2..=0.0,
    ));
    for point in &mut points {
        *point = rect.center() + rotation * (*point - rect.center());
    }

    ui.painter().add(egui::Shape::convex_polygon(
        points,
        visuals.fg_stroke.color,
        Stroke::NONE,
    ));
}

fn settings_diagnostics_accordion_header_layout(
    row_rect: egui::Rect,
    disclosure_width: f32,
) -> SettingsDiagnosticsAccordionHeaderLayout {
    let safe_disclosure_width = disclosure_width.clamp(0.0, row_rect.width());
    let remaining_width = (row_rect.width() - safe_disclosure_width).max(0.0);
    let disclosure_rect = egui::Rect::from_min_size(
        row_rect.min,
        egui::vec2(safe_disclosure_width, row_rect.height()),
    );
    let icon_width = CONTROL_ROW_HEIGHT.min(remaining_width);
    let icon_gap = SETTINGS_ACCORDION_HEADER_ICON_GAP.min((remaining_width - icon_width).max(0.0));
    let title_width = (remaining_width - icon_width - icon_gap).max(0.0);
    let content_rect = egui::Rect::from_min_size(
        egui::pos2(disclosure_rect.right(), row_rect.top()),
        egui::vec2(remaining_width, row_rect.height()),
    );
    let icon_rect = egui::Rect::from_min_size(
        content_rect.min,
        egui::vec2(icon_width, content_rect.height()),
    );
    let title_rect = egui::Rect::from_min_size(
        egui::pos2(icon_rect.right() + icon_gap, content_rect.top()),
        egui::vec2(title_width, content_rect.height()),
    );

    SettingsDiagnosticsAccordionHeaderLayout {
        disclosure_rect,
        icon_rect,
        title_rect,
    }
}

fn draw_settings_diagnostics_accordion_header(
    ui: &mut Ui,
    icon: AppIcon,
    title: &str,
    openness: f32,
) -> egui::Response {
    let row_width = ui.available_width().max(0.0);
    let (row_rect, response) =
        ui.allocate_exact_size(egui::vec2(row_width, CONTROL_ROW_HEIGHT), Sense::click());
    let response = response.on_hover_cursor(egui::CursorIcon::PointingHand);
    let layout = settings_diagnostics_accordion_header_layout(row_rect, ui.spacing().indent);

    if !ui.is_rect_visible(row_rect) {
        return response;
    }

    if layout.disclosure_rect.width() > 0.0 {
        paint_settings_accordion_disclosure_icon(ui, layout.disclosure_rect, openness, &response);
    }

    if layout.icon_rect.width() > 0.0 {
        ui.painter().text(
            layout.icon_rect.center(),
            egui::Align2::CENTER_CENTER,
            format!("{icon}"),
            egui::FontId::proportional(15.0),
            TEXT_PRIMARY,
        );
    }

    if layout.title_rect.width() > 0.0 {
        ui.scope_builder(
            egui::UiBuilder::new()
                .max_rect(layout.title_rect)
                .layout(Layout::left_to_right(Align::Center)),
            |ui| {
                let title_response = ui.add(
                    egui::Label::new(RichText::new(title).strong().size(15.0).color(TEXT_PRIMARY))
                        .truncate(),
                );
                let title_font = egui::TextStyle::Body.resolve(ui.style());
                let _ = with_truncation_tooltip(
                    ui,
                    title_response,
                    title,
                    &title_font,
                    TEXT_PRIMARY,
                    layout.title_rect.width(),
                );
            },
        );
    }

    response
}

fn draw_settings_saved_messages_project_header(
    ui: &mut Ui,
    project_name: &str,
    message_count_text: &str,
    openness: f32,
) -> egui::Response {
    let row_width = ui.available_width().max(0.0);
    let (row_rect, response) =
        ui.allocate_exact_size(egui::vec2(row_width, CONTROL_ROW_HEIGHT), Sense::click());
    let response = response.on_hover_cursor(egui::CursorIcon::PointingHand);
    let count_galley =
        WidgetText::from(RichText::new(message_count_text).small().color(TEXT_MUTED)).into_galley(
            ui,
            Some(TextWrapMode::Truncate),
            row_width,
            egui::TextStyle::Small,
        );
    let layout = settings_saved_messages_project_header_layout(
        row_rect,
        ui.spacing().indent,
        count_galley.size().x.ceil(),
        ui.spacing().item_spacing.x,
    );

    if !ui.is_rect_visible(row_rect) {
        return response;
    }

    if layout.disclosure_rect.width() > 0.0 {
        paint_settings_accordion_disclosure_icon(ui, layout.disclosure_rect, openness, &response);
    }

    if layout.folder_icon_rect.width() > 0.0 {
        ui.painter().text(
            layout.folder_icon_rect.center(),
            egui::Align2::CENTER_CENTER,
            format!("{}", icons::FOLDER_OPEN),
            egui::FontId::proportional(15.0),
            TEXT_PRIMARY,
        );
    }

    if layout.title_rect.width() > 0.0 {
        ui.scope_builder(
            egui::UiBuilder::new()
                .max_rect(layout.title_rect)
                .layout(Layout::left_to_right(Align::Center)),
            |ui| {
                let title_response = ui.add(
                    egui::Label::new(
                        RichText::new(project_name)
                            .strong()
                            .size(15.0)
                            .color(TEXT_PRIMARY),
                    )
                    .truncate(),
                );
                let title_font = egui::TextStyle::Body.resolve(ui.style());
                let _ = with_truncation_tooltip(
                    ui,
                    title_response,
                    project_name,
                    &title_font,
                    TEXT_PRIMARY,
                    layout.title_rect.width(),
                );
            },
        );
    }

    if layout.count_rect.width() > 0.0 {
        ui.scope_builder(
            egui::UiBuilder::new()
                .max_rect(layout.count_rect)
                .layout(Layout::right_to_left(Align::Center)),
            |ui| {
                ui.add(
                    egui::Label::new(RichText::new(message_count_text).small().color(TEXT_MUTED))
                        .truncate(),
                );
            },
        );
    }

    response
}

fn settings_saved_message_card_width(available_width: f32) -> f32 {
    available_width.max(0.0)
}

fn settings_saved_message_text_width(card_width: f32) -> f32 {
    (card_width
        - CONTROL_ROW_HEIGHT
        - SETTINGS_SAVED_MESSAGE_ACTIONS_GAP
        - (SETTINGS_SAVED_MESSAGE_CARD_MARGIN * 2.0))
        .max(0.0)
}

fn settings_saved_messages_project_state_id(project_id: u64) -> Id {
    Id::new(("settings-saved-messages-project", project_id))
}

fn draw_settings_saved_message_card(
    ui: &mut Ui,
    message: &str,
    card_width: f32,
    show_send_action: bool,
) -> (bool, bool) {
    let mut send_clicked = false;
    let mut remove_clicked = false;
    let text_width = settings_saved_message_text_width(card_width);
    ui.with_layout(Layout::left_to_right(Align::Min), |ui| {
        ui.spacing_mut().item_spacing.x = SETTINGS_SAVED_MESSAGE_ACTIONS_GAP;
        settings_surface_frame(
            with_alpha(SURFACE_BG, 188),
            SETTINGS_SAVED_MESSAGE_CARD_MARGIN,
        )
        .show(ui, |ui| {
            ui.set_min_width(text_width);
            ui.set_max_width(text_width);
            ui.add(
                egui::Label::new(
                    RichText::new(message)
                        .size(SETTINGS_SAVED_MESSAGE_TEXT_SIZE)
                        .color(TEXT_PRIMARY),
                )
                .wrap(),
            );
        });
        ui.vertical(|ui| {
            ui.spacing_mut().item_spacing = egui::vec2(0.0, 6.0);
            if show_send_action
                && styled_icon_button(
                    ui,
                    AppIcon::Terminal,
                    BTN_BLUE,
                    BTN_BLUE_HOVER,
                    BTN_ICON_ACTIVE,
                    "Send saved message",
                )
            {
                send_clicked = true;
            }
            if styled_icon_button(
                ui,
                AppIcon::Trash,
                BTN_RED,
                BTN_RED_HOVER,
                Color32::from_rgb(186, 58, 58),
                "Remove saved message",
            ) {
                remove_clicked = true;
            }
        });
    });
    (send_clicked, remove_clicked)
}

fn settings_general_uses_stacked_layout(available_width: f32) -> bool {
    available_width < SETTINGS_GENERAL_STACK_BREAKPOINT
}

fn settings_general_inline_control_width(available_width: f32) -> f32 {
    available_width
        .max(0.0)
        .min(SETTINGS_GENERAL_INLINE_CONTROL_WIDTH)
}

fn show_settings_card<R>(
    ui: &mut Ui,
    icon: AppIcon,
    title: &str,
    description: &str,
    add_contents: impl FnOnce(&mut Ui) -> R,
) -> R {
    settings_surface_frame(with_alpha(SURFACE_BG_SOFT, 228), 12.0)
        .show(ui, |ui| {
            ui.label(
                RichText::new(format!("{icon} {title}"))
                    .strong()
                    .size(15.0)
                    .color(TEXT_PRIMARY),
            );
            if !description.is_empty() {
                ui.label(RichText::new(description).small().color(TEXT_MUTED));
                ui.add_space(10.0);
            }
            add_contents(ui)
        })
        .inner
}

fn resolve_ctrl_c_action(can_copy_selection: bool) -> CtrlCAction {
    if can_copy_selection {
        CtrlCAction::CopySelection
    } else {
        CtrlCAction::SendInterrupt
    }
}

fn terminal_secondary_click_action(
    has_selection: bool,
    can_paste: bool,
) -> TerminalSecondaryClickAction {
    if has_selection {
        TerminalSecondaryClickAction::OpenCopyMenu
    } else if can_paste {
        TerminalSecondaryClickAction::PasteImmediately
    } else {
        TerminalSecondaryClickAction::None
    }
}

fn primary_shortcut_modifier(modifiers: egui::Modifiers) -> bool {
    modifiers.ctrl || modifiers.command
}

fn terminal_link_activation_modifiers(modifiers: egui::Modifiers) -> bool {
    primary_shortcut_modifier(modifiers) && !modifiers.alt && !modifiers.shift
}

fn terminal_link_rules() -> &'static [Rule] {
    static RULES: OnceLock<Vec<Rule>> = OnceLock::new();
    RULES
        .get_or_init(|| {
            vec![
                Rule::new(CLOSING_PARENTHESIS_HYPERLINK_PATTERN, "$0")
                    .expect("valid closing-parenthesis terminal hyperlink regex"),
                Rule::new(GENERIC_HYPERLINK_PATTERN, "$0")
                    .expect("valid generic terminal hyperlink regex"),
            ]
        })
        .as_slice()
}

fn terminal_link_at_point(
    snapshot: &TerminalSelectionSnapshot,
    point: TerminalSelectionPoint,
) -> Option<String> {
    terminal_explicit_link_at_point(snapshot, point)
        .or_else(|| terminal_text_link_at_point(snapshot, point))
}

fn terminal_explicit_link_at_point(
    snapshot: &TerminalSelectionSnapshot,
    point: TerminalSelectionPoint,
) -> Option<String> {
    terminal_selection_hyperlink_at_point(snapshot, point)
        .filter(|uri| terminal_link_uri_allowed(uri))
        .map(str::to_owned)
}

fn terminal_text_link_at_point(
    snapshot: &TerminalSelectionSnapshot,
    point: TerminalSelectionPoint,
) -> Option<String> {
    let logical_line = terminal_logical_line(snapshot, point.row)?;
    let byte_index = terminal_logical_line_byte_index(&logical_line, point)?;
    Rule::match_hyperlinks(&logical_line.text, terminal_link_rules())
        .into_iter()
        .find(|matched| {
            matched.range.contains(&byte_index) && terminal_link_uri_allowed(matched.link.uri())
        })
        .map(|matched| matched.link.uri().to_owned())
}

fn terminal_link_uri_allowed(uri: &str) -> bool {
    terminal_link_has_ascii_case_insensitive_prefix(uri, "http://")
        || terminal_link_has_ascii_case_insensitive_prefix(uri, "https://")
}

fn terminal_link_has_ascii_case_insensitive_prefix(uri: &str, prefix: &str) -> bool {
    uri.get(..prefix.len())
        .is_some_and(|candidate| candidate.eq_ignore_ascii_case(prefix))
}

fn terminal_selection_hyperlink_at_point(
    snapshot: &TerminalSelectionSnapshot,
    point: TerminalSelectionPoint,
) -> Option<&str> {
    snapshot
        .lines
        .get(point.row)?
        .hyperlinks
        .iter()
        .find(|hyperlink| {
            point.column >= hyperlink.start_column && point.column < hyperlink.end_column
        })
        .map(|hyperlink| hyperlink.uri.as_str())
}

fn should_resolve_terminal_link(
    link_activation_modifiers_active: bool,
    primary_pressed_on_terminal: bool,
    has_pending_link_click: bool,
) -> bool {
    link_activation_modifiers_active || primary_pressed_on_terminal || has_pending_link_click
}

fn terminal_logical_line(
    snapshot: &TerminalSelectionSnapshot,
    row: usize,
) -> Option<TerminalLogicalLine> {
    let (start_row, end_row) = terminal_logical_line_row_range(snapshot, row)?;
    let mut logical_line = TerminalLogicalLine::default();

    for row in start_row..=end_row {
        append_terminal_logical_line_row(
            &mut logical_line.text,
            &mut logical_line.segments,
            row,
            &snapshot.lines[row],
        );
    }

    Some(logical_line)
}

fn terminal_logical_line_row_range(
    snapshot: &TerminalSelectionSnapshot,
    row: usize,
) -> Option<(usize, usize)> {
    if row >= snapshot.lines.len() {
        return None;
    }

    let mut start_row = row;
    while start_row > 0 && snapshot.lines[start_row - 1].wraps_to_next {
        start_row -= 1;
    }

    let mut end_row = row;
    while end_row + 1 < snapshot.lines.len() && snapshot.lines[end_row].wraps_to_next {
        end_row += 1;
    }

    Some((start_row, end_row))
}

fn append_terminal_logical_line_row(
    text: &mut String,
    segments: &mut Vec<TerminalLinkSegment>,
    row: usize,
    line: &TerminalSelectionLine,
) {
    let mut column = 0;

    for cell in &line.cells {
        if cell.column > column {
            append_terminal_logical_segment(
                text,
                segments,
                row,
                column,
                cell.column.min(line.width),
                &" ".repeat(cell.column.min(line.width).saturating_sub(column)),
            );
            column = cell.column.min(line.width);
        }

        let end_column = cell
            .column
            .saturating_add(cell.display_width.max(1))
            .min(line.width);
        if end_column <= cell.column {
            continue;
        }

        append_terminal_logical_segment(
            text,
            segments,
            row,
            cell.column,
            end_column,
            &cell.rendered_text(),
        );
        column = end_column;
    }

    if column < line.width {
        append_terminal_logical_segment(
            text,
            segments,
            row,
            column,
            line.width,
            &" ".repeat(line.width - column),
        );
    }
}

fn append_terminal_logical_segment(
    text: &mut String,
    segments: &mut Vec<TerminalLinkSegment>,
    row: usize,
    start_column: usize,
    end_column: usize,
    segment_text: &str,
) {
    if end_column <= start_column || segment_text.is_empty() {
        return;
    }

    let byte_start = text.len();
    text.push_str(segment_text);
    segments.push(TerminalLinkSegment {
        row,
        start_column,
        end_column,
        byte_range: byte_start..text.len(),
    });
}

fn terminal_logical_line_byte_index(
    logical_line: &TerminalLogicalLine,
    point: TerminalSelectionPoint,
) -> Option<usize> {
    let segment = logical_line.segments.iter().find(|segment| {
        segment.row == point.row
            && point.column >= segment.start_column
            && point.column < segment.end_column
    })?;
    let segment_text = &logical_line.text[segment.byte_range.clone()];
    let byte_offset =
        byte_index_for_display_column(segment_text, point.column - segment.start_column);
    Some(segment.byte_range.start + byte_offset)
}

fn byte_index_for_display_column(text: &str, column_offset: usize) -> usize {
    if column_offset == 0 {
        return 0;
    }

    let mut seen_columns = 0;
    for (byte_index, ch) in text.char_indices() {
        if seen_columns >= column_offset {
            return byte_index;
        }

        let width = unicode_width::UnicodeWidthChar::width(ch).unwrap_or(0);
        if width == 0 {
            continue;
        }

        let next_columns = seen_columns.saturating_add(width);
        if next_columns > column_offset {
            return byte_index;
        }

        seen_columns = next_columns;
    }

    text.len()
}

fn terminal_selection_point_from_pointer(
    pointer_pos: Option<egui::Pos2>,
    origin: egui::Pos2,
    snapshot: &TerminalSelectionSnapshot,
    char_width: f32,
    galley: &Galley,
) -> Option<TerminalSelectionPoint> {
    let pointer_pos = pointer_pos?;
    if snapshot.lines.is_empty() || galley.rows.is_empty() || char_width <= 0.0 {
        return None;
    }

    let max_row = snapshot
        .lines
        .len()
        .saturating_sub(1)
        .min(galley.rows.len().saturating_sub(1));
    let cursor = galley.cursor_from_pos(pointer_pos - origin);
    let row = cursor.rcursor.row.min(max_row);
    let line_width = terminal_selection_line_width(&snapshot.lines[row]);
    let column =
        (((pointer_pos.x - origin.x).max(0.0) / char_width).floor() as usize).min(line_width);

    Some(TerminalSelectionPoint { row, column })
}

fn terminal_selection_row_rect(
    galley: &Galley,
    origin: egui::Pos2,
    row: usize,
) -> Option<egui::Rect> {
    galley
        .rows
        .get(row)
        .map(|galley_row| galley_row.rect.translate(origin.to_vec2()))
}

fn terminal_cell_metric(metric: f32) -> f32 {
    if metric.is_finite() {
        metric.max(1.0)
    } else {
        1.0
    }
}

fn average_terminal_cell_width(sample_width: f32, sample_cells: usize) -> f32 {
    let sample_cells = sample_cells.max(1) as f32;
    terminal_cell_metric(sample_width / sample_cells)
}

fn terminal_font_family() -> FontFamily {
    FontFamily::Name(TERMINAL_FONT_FAMILY_NAME.into())
}

fn terminal_font_id(style: &egui::Style) -> FontId {
    let mut font_id = egui::TextStyle::Monospace.resolve(style);
    font_id.family = terminal_font_family();
    font_id
}

fn terminal_line_height(ui: &Ui, font_id: &FontId) -> f32 {
    terminal_cell_metric(ui.fonts(|fonts| fonts.row_height(font_id)))
}

fn terminal_char_width(ui: &Ui, font_id: &FontId) -> f32 {
    let sample_width = ui.fonts(|fonts| {
        let mut layout_job = LayoutJob::default();
        layout_job.wrap.max_width = f32::INFINITY;
        layout_job.append(
            &"W".repeat(TERMINAL_CHAR_WIDTH_SAMPLE_CELLS),
            0.0,
            TextFormat {
                font_id: font_id.clone(),
                ..TextFormat::default()
            },
        );
        fonts.layout_job(layout_job).size().x
    });
    average_terminal_cell_width(sample_width, TERMINAL_CHAR_WIDTH_SAMPLE_CELLS)
}

fn configure_terminal_font_family(fonts: &mut egui::FontDefinitions) {
    let fallback_font_names = load_terminal_fallback_font_names(fonts);
    install_terminal_font_family(fonts, &fallback_font_names);
}

fn install_terminal_font_family(fonts: &mut egui::FontDefinitions, fallback_font_names: &[String]) {
    let icon_font_names = icon_fonts()
        .iter()
        .map(|asset| asset.family.to_owned())
        .collect::<HashSet<_>>();
    let mut terminal_family = Vec::new();
    let mut seen_font_names = HashSet::new();

    for font_name in fallback_font_names.iter().chain(
        fonts
            .families
            .get(&FontFamily::Monospace)
            .into_iter()
            .flatten(),
    ) {
        if icon_font_names.contains(font_name) || !fonts.font_data.contains_key(font_name) {
            continue;
        }

        if seen_font_names.insert(font_name.clone()) {
            terminal_family.push(font_name.clone());
        }
    }

    fonts
        .families
        .insert(terminal_font_family(), terminal_family);
}

#[cfg(target_os = "windows")]
fn windows_terminal_font_candidates() -> &'static [(&'static str, &'static str)] {
    &WINDOWS_TERMINAL_FONT_CANDIDATES
}

#[cfg(target_os = "windows")]
fn load_terminal_fallback_font_names(fonts: &mut egui::FontDefinitions) -> Vec<String> {
    let fonts_dir = std::env::var_os("WINDIR")
        .map(PathBuf::from)
        .map(|windir| windir.join("Fonts"))
        .unwrap_or_else(|| PathBuf::from(r"C:\Windows\Fonts"));
    let mut loaded_font_names = Vec::new();

    // Load embedded Nerd Font for terminal icon support
    fonts.font_data.insert(
        NERD_FONT_NAME.to_owned(),
        FontData::from_owned(NERD_FONT_DATA.to_vec()),
    );
    loaded_font_names.push(NERD_FONT_NAME.to_owned());

    for (font_name, file_name) in windows_terminal_font_candidates() {
        let font_path = fonts_dir.join(file_name);
        let Ok(font_bytes) = fs::read(&font_path) else {
            continue;
        };

        fonts
            .font_data
            .insert((*font_name).to_owned(), FontData::from_owned(font_bytes));
        loaded_font_names.push((*font_name).to_owned());
    }

    loaded_font_names
}

#[cfg(not(target_os = "windows"))]
fn load_terminal_fallback_font_names(_fonts: &mut egui::FontDefinitions) -> Vec<String> {
    Vec::new()
}

fn terminal_grid_dimensions(output_size: Vec2, char_width: f32, line_height: f32) -> (u16, u16) {
    let char_width = terminal_cell_metric(char_width);
    let line_height = terminal_cell_metric(line_height);
    let cols = ((output_size.x.max(0.0) / char_width).floor() as u16).max(8);
    let lines = ((output_size.y.max(0.0) / line_height).floor() as u16).max(3);
    (cols, lines)
}

fn force_terminal_pane_width(ui: &mut Ui, pane_width: f32) -> f32 {
    let pane_width = pane_width.max(0.0);
    let pane_right = ui.max_rect().left() + pane_width;
    ui.set_width(pane_width);
    ui.set_min_width(pane_width);
    ui.expand_to_include_x(pane_right);
    pane_right
}

fn terminal_output_viewport_size(output_size: Vec2) -> Vec2 {
    egui::vec2(output_size.x.max(0.0), output_size.y.max(0.0))
}

fn terminal_output_surface_size(output_size: Vec2, content_height: f32) -> Vec2 {
    egui::vec2(
        output_size.x.max(0.0),
        output_size.y.max(content_height.max(0.0)),
    )
}

#[derive(Debug, Clone, Copy, PartialEq)]
struct TerminalOutputScrollBehavior {
    vertical_offset: Option<f32>,
    stick_to_bottom: bool,
    keep_activation_alignment_pending: bool,
}

fn terminal_output_scroll_behavior(
    terminal: &TerminalEntry,
    line_height: f32,
    viewport_height: f32,
) -> TerminalOutputScrollBehavior {
    let has_content = !terminal.render_cache.lines.is_empty();
    let activation_offset = terminal
        .activation_scroll_align_pending
        .then(|| {
            terminal_activation_scroll_offset(
                &terminal.render_cache,
                terminal.stable_input_cursor_row,
                line_height,
                viewport_height,
            )
        })
        .flatten();
    let prompt_anchor_offset = activation_offset.or_else(|| {
        terminal_prompt_scroll_anchor_enabled(terminal)
            .then(|| {
                terminal_activation_scroll_offset(
                    &terminal.render_cache,
                    terminal.stable_input_cursor_row,
                    line_height,
                    viewport_height,
                )
            })
            .flatten()
    });

    // Disable stick_to_bottom while selection drag is active to allow autoscroll
    let selection_drag_active = terminal.selection_drag_active;

    TerminalOutputScrollBehavior {
        vertical_offset: prompt_anchor_offset,
        stick_to_bottom: has_content && prompt_anchor_offset.is_none() && !selection_drag_active,
        keep_activation_alignment_pending: terminal.activation_scroll_align_pending && !has_content,
    }
}

fn terminal_prompt_scroll_anchor_enabled(terminal: &TerminalEntry) -> bool {
    terminal.ai_session.tool == Some(AiCliTool::CodexCli)
        && !terminal.prompt_scroll_anchor_detached
        && (terminal.codex_session_active
            || terminal.codex_launch_pending_since.is_some()
            || terminal.ai_session.status != AiCliStatus::Inactive)
}

fn reset_terminal_prompt_scroll_anchor(terminal: &mut TerminalEntry) {
    terminal.prompt_scroll_anchor_detached = false;
}

fn detach_terminal_prompt_scroll_anchor_on_manual_scroll(terminal: &mut TerminalEntry) {
    if terminal_prompt_scroll_anchor_enabled(terminal) {
        terminal.prompt_scroll_anchor_detached = true;
    }
}

fn terminal_activation_scroll_offset(
    snapshot: &TerminalSnapshot,
    stable_input_cursor_row: Option<usize>,
    line_height: f32,
    viewport_height: f32,
) -> Option<f32> {
    if snapshot.lines.is_empty() {
        return None;
    }

    let max_row = snapshot.lines.len().saturating_sub(1);
    let clamped_target_row =
        terminal_scroll_anchor_row(snapshot, stable_input_cursor_row)?.min(max_row);
    let content_height = snapshot.lines.len() as f32 * line_height.max(0.0);
    let max_offset = (content_height - viewport_height.max(0.0)).max(0.0);
    let visible_rows = if line_height > 0.0 {
        (viewport_height.max(0.0) / line_height).floor().max(1.0) as usize
    } else {
        1
    };
    let preferred_top_row = clamped_target_row
        .saturating_add(1)
        .saturating_sub(visible_rows);
    Some((preferred_top_row as f32 * line_height.max(0.0)).clamp(0.0, max_offset))
}

fn terminal_scroll_anchor_row(
    snapshot: &TerminalSnapshot,
    stable_input_cursor_row: Option<usize>,
) -> Option<usize> {
    if snapshot.lines.is_empty() {
        return None;
    }

    let max_row = snapshot.lines.len().saturating_sub(1);
    let prompt_row = stable_input_cursor_row
        .filter(|row| *row <= max_row)
        .or_else(|| {
            snapshot
                .cursor
                .map(|cursor| cursor.y)
                .filter(|row| *row <= max_row)
        });
    let last_non_empty_row = terminal_last_non_empty_row(snapshot);

    match (prompt_row, last_non_empty_row) {
        (Some(prompt_row), Some(last_non_empty_row)) => Some(prompt_row.max(last_non_empty_row)),
        (Some(prompt_row), None) => Some(prompt_row),
        (None, Some(last_non_empty_row)) => Some(last_non_empty_row),
        (None, None) => stable_input_cursor_row
            .or_else(|| snapshot.cursor.map(|cursor| cursor.y))
            .map(|row| row.min(max_row)),
    }
}

/// Calculates autoscroll delta for selection drag when pointer is near viewport edges.
/// This is a generic helper used by both terminal and file editor selection workflows.
///
/// Returns positive value to scroll up (content moves up, revealing content above)
/// or negative value to scroll down (content moves down, revealing content below).
/// Returns 0.0 when pointer is in the safe zone.
fn selection_edge_autoscroll_delta(
    pointer_pos: Option<egui::Pos2>,
    viewport_rect: egui::Rect,
    line_height: f32,
) -> f32 {
    let Some(pos) = pointer_pos else {
        return 0.0;
    };

    if !line_height.is_finite() || line_height <= 0.0 {
        return 0.0;
    }

    // Safety zone margin from viewport edges
    const SAFETY_ZONE_LINES: f32 = 1.5;
    let safety_margin = line_height * SAFETY_ZONE_LINES;

    // Check if pointer is above the top edge (outside viewport)
    let distance_above = viewport_rect.min.y - pos.y;
    if distance_above > 0.0 {
        // Pointer is above the viewport - scroll up (positive delta)
        let proximity = safety_margin + distance_above;
        return selection_edge_autoscroll_speed(proximity, line_height);
    }

    // Check if pointer is near the top edge (within safety margin inside viewport)
    let distance_from_top = pos.y - viewport_rect.min.y;
    if distance_from_top < safety_margin {
        // Pointer is near the top edge inside viewport - scroll up (positive delta)
        let proximity = safety_margin - distance_from_top;
        return selection_edge_autoscroll_speed(proximity, line_height);
    }

    // Check if pointer is below the bottom edge (outside viewport)
    let distance_below = pos.y - viewport_rect.max.y;
    if distance_below > 0.0 {
        // Pointer is below the viewport - scroll down (negative delta)
        let proximity = safety_margin + distance_below;
        return -selection_edge_autoscroll_speed(proximity, line_height);
    }

    // Check if pointer is near the bottom edge (within safety margin inside viewport)
    let distance_from_bottom = viewport_rect.max.y - pos.y;
    if distance_from_bottom < safety_margin {
        // Pointer is near the bottom edge inside viewport - scroll down (negative delta)
        let proximity = safety_margin - distance_from_bottom;
        return -selection_edge_autoscroll_speed(proximity, line_height);
    }

    // Pointer is in the safe zone (neither near top nor bottom)
    0.0
}

/// Calculates autoscroll speed based on pointer proximity to viewport edge.
/// Returns speed in pixels per frame (to be applied via scroll_with_delta).
/// Distance is measured from the edge of the safety zone outward.
fn selection_edge_autoscroll_speed(proximity: f32, line_height: f32) -> f32 {
    // Minimum speed: 1 line per frame
    let min_speed = line_height;
    // Maximum speed: 8 lines per frame
    let max_speed = line_height * 8.0;

    // Calculate speed factor based on proximity (pixels beyond safety zone)
    // Starts slow at the edge, gets faster as pointer moves further away
    let speed_factor = (proximity / line_height).clamp(0.0, 6.0);

    // Interpolate between min and max speed
    let speed = min_speed + (max_speed - min_speed) * (speed_factor / 6.0);

    speed.clamp(min_speed, max_speed)
}

/// Helper to calculate terminal selection autoscroll delta (wrapper for generic helper).
fn terminal_selection_autoscroll_delta(
    pointer_pos: Option<egui::Pos2>,
    viewport_rect: egui::Rect,
    line_height: f32,
) -> f32 {
    selection_edge_autoscroll_delta(pointer_pos, viewport_rect, line_height)
}

/// Helper to calculate terminal selection autoscroll speed (wrapper for generic helper).
fn terminal_selection_autoscroll_speed(proximity: f32, line_height: f32) -> f32 {
    selection_edge_autoscroll_speed(proximity, line_height)
}

fn terminal_last_non_empty_row(snapshot: &TerminalSnapshot) -> Option<usize> {
    snapshot.lines.iter().rposition(|line| {
        line.runs
            .iter()
            .any(|run| !run.text.trim_end_matches(' ').is_empty())
    })
}

fn allocate_terminal_output_surface(
    ui: &mut Ui,
    output_size: Vec2,
    content_height: f32,
    sense: Sense,
) -> (egui::Rect, egui::Response) {
    ui.allocate_exact_size(
        terminal_output_surface_size(output_size, content_height),
        sense,
    )
}

fn terminal_selection_text(
    snapshot: &TerminalSelectionSnapshot,
    selection: Option<&TerminalSelection>,
) -> Option<String> {
    let selection = selection?;
    if !selection.has_selection() || snapshot.lines.is_empty() {
        return None;
    }

    let (start, end) = selection.normalized();
    let last_row = snapshot.lines.len().saturating_sub(1);
    let start_row = start.row.min(last_row);
    let end_row = end.row.min(last_row);

    let mut rendered = String::new();
    for row in start_row..=end_row {
        let line = &snapshot.lines[row];
        let line_width = terminal_selection_line_width(line);
        let start_column = if row == start_row {
            start.column.min(line_width)
        } else {
            0
        };
        let end_column = if row == end_row {
            end.column.min(line_width)
        } else {
            line_width
        };
        if row > start_row && !snapshot.lines[row - 1].wraps_to_next {
            rendered.push('\n');
        }
        rendered.push_str(&slice_terminal_line_columns(line, start_column, end_column));
    }

    Some(rendered)
}

fn terminal_selection_line_width(line: &TerminalSelectionLine) -> usize {
    line.width
}

fn slice_terminal_line_columns(line: &TerminalSelectionLine, start: usize, end: usize) -> String {
    if end <= start {
        return String::new();
    }

    let mut rendered = String::new();
    let mut column = start;

    for cell in &line.cells {
        let cell_end = cell.column.saturating_add(cell.display_width.max(1));
        if cell_end <= start {
            continue;
        }
        if cell.column >= end {
            break;
        }

        if cell.column > column {
            rendered.push_str(&" ".repeat(cell.column.min(end).saturating_sub(column)));
        }

        rendered.push_str(&cell.rendered_text());
        column = cell_end;
    }

    if column < end {
        rendered.push_str(&" ".repeat(end - column));
    }

    rendered
}

fn paint_terminal_selection(
    ui: &mut Ui,
    origin: egui::Pos2,
    snapshot: &TerminalSelectionSnapshot,
    selection: Option<&TerminalSelection>,
    char_width: f32,
    galley: &Galley,
) {
    if snapshot.lines.is_empty() || galley.rows.is_empty() {
        return;
    }

    let Some(selection) = selection.filter(|selection| selection.has_selection()) else {
        return;
    };

    let (start, end) = selection.normalized();
    let fill = with_alpha(ui.visuals().selection.bg_fill, 92);

    let max_row = end
        .row
        .min(snapshot.lines.len().saturating_sub(1))
        .min(galley.rows.len().saturating_sub(1));

    for row in start.row.min(max_row)..=max_row {
        let line_width = terminal_selection_line_width(&snapshot.lines[row]);
        let start_column = if row == start.row {
            start.column.min(line_width)
        } else {
            0
        };
        let end_column = if row == end.row {
            end.column.min(line_width)
        } else {
            line_width
        };

        if end_column <= start_column {
            continue;
        }

        let Some(row_rect) = terminal_selection_row_rect(galley, origin, row) else {
            continue;
        };
        let rect = egui::Rect::from_min_size(
            egui::pos2(origin.x + start_column as f32 * char_width, row_rect.top()),
            egui::vec2(
                (end_column - start_column) as f32 * char_width,
                row_rect.height(),
            ),
        );
        ui.painter().rect_filled(rect, 2.0, fill);
    }
}

fn build_terminal_render(
    snapshot: &TerminalSnapshot,
    font_id: &FontId,
    terminal_exited: bool,
    shell: ShellKind,
    stable_input_cursor_row: Option<usize>,
    time_seconds: f64,
) -> TerminalRenderModel {
    let visible_cursor = visible_terminal_cursor(
        snapshot.cursor,
        terminal_exited,
        shell,
        stable_input_cursor_row,
        time_seconds,
    );
    let cursor_overlay =
        visible_cursor.and_then(|cursor| build_terminal_cursor_overlay(snapshot, cursor));
    let mut job = LayoutJob::default();
    job.wrap.max_width = f32::INFINITY;

    for (line_index, line) in snapshot.lines.iter().enumerate() {
        let block_cursor = visible_cursor
            .filter(|cursor| cursor.y == line_index && cursor.shape == TerminalCursorShape::Block);

        if let (Some(cursor), Some(cursor_line)) = (block_cursor, snapshot.cursor_line.as_ref()) {
            if cursor_line.row == line_index {
                for cell in &cursor_line.cells {
                    let style = if cell.covers_column(cursor.x) {
                        invert_terminal_style(cell.style)
                    } else {
                        cell.style
                    };
                    append_terminal_text(&mut job, &cell.rendered_text(), style, font_id);
                }
            } else {
                for run in &line.runs {
                    append_terminal_text(&mut job, &run.text, run.style, font_id);
                }
            }
        } else if let Some(cursor_line) = snapshot.cursor_line.as_ref() {
            if cursor_line.row == line_index {
                for cell in &cursor_line.cells {
                    append_terminal_text(&mut job, &cell.rendered_text(), cell.style, font_id);
                }
            } else {
                for run in &line.runs {
                    append_terminal_text(&mut job, &run.text, run.style, font_id);
                }
            }
        } else {
            for run in &line.runs {
                append_terminal_text(&mut job, &run.text, run.style, font_id);
            }
        }

        if line_index + 1 < snapshot.lines.len() {
            job.append(
                "\n",
                0.0,
                TextFormat {
                    font_id: font_id.clone(),
                    ..TextFormat::default()
                },
            );
        }
    }

    TerminalRenderModel {
        layout_job: job,
        cursor_overlay,
    }
}

fn build_terminal_cursor_overlay(
    snapshot: &TerminalSnapshot,
    cursor: TerminalCursor,
) -> Option<TerminalCursorOverlay> {
    if cursor.shape == TerminalCursorShape::Block {
        return None;
    }

    let color = snapshot
        .cursor_line
        .as_ref()
        .filter(|line| line.row == cursor.y)
        .and_then(|line| line.cell_covering_column(cursor.x))
        .map(|cell| to_egui_color(cell.style.fg))
        .unwrap_or(TEXT_PRIMARY);

    Some(TerminalCursorOverlay {
        shape: cursor.shape,
        row: cursor.y,
        column: cursor.x,
        width_columns: 1,
        color,
    })
}

fn visible_terminal_cursor(
    cursor: Option<TerminalCursor>,
    terminal_exited: bool,
    shell: ShellKind,
    stable_input_cursor_row: Option<usize>,
    time_seconds: f64,
) -> Option<TerminalCursor> {
    cursor.filter(|cursor| {
        !terminal_exited
            && !cursor_hidden_by_row_filter(shell, stable_input_cursor_row, cursor.y)
            && (!cursor.blinking || terminal_cursor_blink_phase_visible(time_seconds))
    })
}

fn terminal_cursor_blink_phase_visible(time_seconds: f64) -> bool {
    ((time_seconds / CURSOR_BLINK_STEP_SECS).floor() as u64) % 2 == 0
}

fn cursor_hidden_by_row_filter(
    shell: ShellKind,
    stable_input_cursor_row: Option<usize>,
    cursor_row: usize,
) -> bool {
    shell == ShellKind::PowerShell && stable_input_cursor_row != Some(cursor_row)
}

fn sync_terminal_cursor_row_state(terminal: &mut TerminalEntry, time_seconds: f64) {
    let current_cursor_row = terminal.render_cache.cursor.map(|cursor| cursor.y);

    if terminal.shell != ShellKind::PowerShell {
        terminal.last_cursor_row = current_cursor_row;
        terminal.last_cursor_row_changed_at = None;
        terminal.stable_input_cursor_row = current_cursor_row;
        return;
    }

    update_stable_cursor_row(
        &mut terminal.last_cursor_row,
        &mut terminal.last_cursor_row_changed_at,
        &mut terminal.stable_input_cursor_row,
        current_cursor_row,
        time_seconds,
    );
}

fn update_stable_cursor_row(
    last_cursor_row: &mut Option<usize>,
    last_cursor_row_changed_at: &mut Option<f64>,
    stable_input_cursor_row: &mut Option<usize>,
    current_cursor_row: Option<usize>,
    time_seconds: f64,
) {
    if current_cursor_row != *last_cursor_row {
        *last_cursor_row = current_cursor_row;
        *last_cursor_row_changed_at = Some(time_seconds);
    }

    let Some(current_cursor_row) = current_cursor_row else {
        *stable_input_cursor_row = None;
        return;
    };

    if *stable_input_cursor_row == Some(current_cursor_row) {
        return;
    }

    if last_cursor_row_changed_at.is_some_and(|changed_at| {
        time_seconds >= changed_at
            && (time_seconds - changed_at) >= POWERSHELL_CURSOR_ROW_STABLE_SECS
    }) {
        *stable_input_cursor_row = Some(current_cursor_row);
    }
}

fn invert_terminal_style(style: crate::terminal::TerminalStyle) -> crate::terminal::TerminalStyle {
    crate::terminal::TerminalStyle {
        fg: style.bg,
        bg: style.fg,
        ..style
    }
}

fn append_terminal_text(
    job: &mut LayoutJob,
    text: &str,
    style: crate::terminal::TerminalStyle,
    font_id: &FontId,
) {
    let fg = to_egui_color(style.fg);
    let mut format = TextFormat {
        font_id: font_id.clone(),
        color: fg,
        background: normalize_terminal_background(style.bg),
        italics: style.italic,
        ..TextFormat::default()
    };

    if style.underline {
        format.underline = Stroke::new(1.0, fg);
    }
    if style.strike {
        format.strikethrough = Stroke::new(1.0, fg);
    }

    job.append(text, 0.0, format);
}

fn paint_terminal_cursor(
    ui: &mut Ui,
    origin: egui::Pos2,
    char_width: f32,
    line_height: f32,
    overlay: TerminalCursorOverlay,
) {
    if overlay.shape == TerminalCursorShape::Block {
        return;
    }

    let rect = terminal_cursor_overlay_rect(origin, char_width, line_height, overlay);
    ui.painter().rect_filled(rect, 0.0, overlay.color);
}

fn terminal_cursor_overlay_rect(
    origin: egui::Pos2,
    char_width: f32,
    line_height: f32,
    overlay: TerminalCursorOverlay,
) -> egui::Rect {
    let x = origin.x + (overlay.column as f32 * char_width);
    let y = origin.y + (overlay.row as f32 * line_height);
    let width = (overlay.width_columns.max(1) as f32 * char_width).max(1.0);

    match overlay.shape {
        TerminalCursorShape::Bar => egui::Rect::from_min_size(
            egui::pos2(x, y),
            egui::vec2(CURSOR_BAR_WIDTH_PX.min(width), line_height),
        ),
        TerminalCursorShape::Underline => {
            let height = CURSOR_UNDERLINE_HEIGHT_PX.min(line_height.max(1.0));
            egui::Rect::from_min_size(
                egui::pos2(x, y + line_height - height),
                egui::vec2(width, height),
            )
        }
        TerminalCursorShape::Block => {
            egui::Rect::from_min_size(egui::pos2(x, y), egui::vec2(width, line_height))
        }
    }
}

fn to_egui_color(color: TerminalColor) -> Color32 {
    Color32::from_rgb(color.r, color.g, color.b)
}

fn normalize_terminal_background(color: TerminalColor) -> Color32 {
    let mapped = to_egui_color(color);
    if color.r <= 6 && color.g <= 6 && color.b <= 6 {
        TERMINAL_OUTPUT_BG
    } else {
        mapped
    }
}

