    fn project_group_header_hover_targets(
        ctx: &Context,
        row_width: f32,
        diff_summary: &super::TerminalManagerDiffSummaryModel,
    ) -> (egui::Pos2, egui::Pos2) {
        let mut app = test_app(std::iter::empty(), None);
        let mut observed = None;
        let _ = ctx.run(RawInput::default(), |ctx| {
            egui::CentralPanel::default().show(ctx, |ui| {
                ui.allocate_ui_with_layout(
                    egui::vec2(row_width, super::CONTROL_ROW_HEIGHT),
                    egui::Layout::left_to_right(egui::Align::Center),
                    |ui| {
                        let (response, _, _, _) = super::draw_project_group_header(
                            &mut app,
                            ui,
                            "Demo Project",
                            false,
                            false,
                            TerminalKind::Foreground,
                            &[],
                            diff_summary,
                            false,
                        );
                        observed = Some(response.rect);
                    },
                );
            });
        });

        let body_rect = observed.expect("expected project group header rect");
        let title_hover_pos = pos2(body_rect.left() + 28.0, body_rect.center().y);
        let action_hover_pos = pos2(
            body_rect.right() + (super::CONTROL_ROW_HEIGHT * 0.5),
            body_rect.center().y,
        );

        (title_hover_pos, action_hover_pos)
    }

