    #[test]
    fn terminal_activation_scroll_offset_clamps_out_of_bounds_cursor() {
        // Regression: when cursor.y is absolute (e.g., 1200) but snapshot is truncated
        // to fewer lines (e.g., 10), the offset should clamp to visible bounds instead
        // of scrolling far down toward the absolute row.
        let snapshot = TerminalSnapshot {
            lines: vec![
                TerminalStyledLine {
                    runs: vec![TerminalStyledRun {
                        text: "line0".to_owned(),
                        style: test_terminal_style(),
                        column: 0,
                        display_width: 5,
                    }],
                },
                TerminalStyledLine {
                    runs: vec![TerminalStyledRun {
                        text: "line1".to_owned(),
                        style: test_terminal_style(),
                        column: 0,
                        display_width: 5,
                    }],
                },
                TerminalStyledLine {
                    runs: vec![TerminalStyledRun {
                        text: "line2".to_owned(),
                        style: test_terminal_style(),
                        column: 0,
                        display_width: 5,
                    }],
                },
                TerminalStyledLine {
                    runs: vec![TerminalStyledRun {
                        text: "line3".to_owned(),
                        style: test_terminal_style(),
                        column: 0,
                        display_width: 5,
                    }],
                },
                TerminalStyledLine {
                    runs: vec![TerminalStyledRun {
                        text: "line4".to_owned(),
                        style: test_terminal_style(),
                        column: 0,
                        display_width: 5,
                    }],
                },
                TerminalStyledLine {
                    runs: vec![TerminalStyledRun {
                        text: "line5".to_owned(),
                        style: test_terminal_style(),
                        column: 0,
                        display_width: 5,
                    }],
                },
                TerminalStyledLine {
                    runs: vec![TerminalStyledRun {
                        text: "line6".to_owned(),
                        style: test_terminal_style(),
                        column: 0,
                        display_width: 5,
                    }],
                },
                TerminalStyledLine {
                    runs: vec![TerminalStyledRun {
                        text: "line7".to_owned(),
                        style: test_terminal_style(),
                        column: 0,
                        display_width: 5,
                    }],
                },
                TerminalStyledLine {
                    runs: vec![TerminalStyledRun {
                        text: "line8".to_owned(),
                        style: test_terminal_style(),
                        column: 0,
                        display_width: 5,
                    }],
                },
                TerminalStyledLine {
                    runs: vec![TerminalStyledRun {
                        text: "prompt".to_owned(),
                        style: test_terminal_style(),
                        column: 0,
                        display_width: 6,
                    }],
                },
            ],
            // Cursor at absolute row 100, but snapshot only has 10 lines
            cursor: Some(TerminalCursor {
                x: 0,
                y: 100,
                shape: TerminalCursorShape::Block,
                blinking: false,
            }),
            cursor_line: None,
        };

        let offset = terminal_activation_scroll_offset(&snapshot, None, 10.0, 60.0);

        // Without clamping, this would try to scroll toward the out-of-bounds row.
        // With clamping, target_row (100) is clamped to max_row (9),
        // then preferred_top_row = 9 + 1 - 6 visible rows = 4.
        assert_eq!(offset, Some(40.0));
    }

