    #[test]
    fn ai_badge_visuals_match_status() {
        use crate::hooks::ClaudeTransportStatus;

        // Without normalized status - pending=true shows pulse
        assert_eq!(
            ai_badge_visual(
                AiCliStatus::Running,
                None,
                None,
                None,
                false,
                None,
                false,
                None
            ),
            Some(AiBadgeVisual::Spinner(Color32::from_rgb(180, 180, 180)))
        );
        assert_eq!(
            ai_badge_visual(
                AiCliStatus::Attention,
                None,
                None,
                None,
                false,
                None,
                true,
                None
            ),
            Some(AiBadgeVisual::Pulse(Color32::from_rgb(220, 220, 220)))
        );
        // Without normalized status - pending=false shows solid
        assert_eq!(
            ai_badge_visual(
                AiCliStatus::Attention,
                None,
                None,
                None,
                false,
                None,
                false,
                None
            ),
            Some(AiBadgeVisual::Solid(Color32::from_rgb(180, 180, 180)))
        );
        assert_eq!(
            ai_badge_visual(
                AiCliStatus::Inactive,
                None,
                None,
                None,
                false,
                None,
                false,
                None
            ),
            None
        );

        // Codex uses the same colors as OpenCode: working gray, permission amber, idle green.
        assert_eq!(
            ai_badge_visual(
                AiCliStatus::Attention,
                Some(CodexTransportStatus::Permission),
                None,
                None,
                true,
                Some(CodexAttentionReason::UserInputRequested),
                false,
                None
            ),
            Some(AiBadgeVisual::Pulse(Color32::from_rgb(220, 180, 100)))
        );
        assert_eq!(
            ai_badge_visual(
                AiCliStatus::Attention,
                Some(CodexTransportStatus::Idle),
                None,
                None,
                false,
                Some(CodexAttentionReason::TurnComplete),
                false,
                None
            ),
            None
        );
        assert_eq!(
            ai_badge_visual(
                AiCliStatus::Attention,
                Some(CodexTransportStatus::Idle),
                None,
                None,
                false,
                Some(CodexAttentionReason::ExecutionError),
                false,
                None
            ),
            Some(AiBadgeVisual::Solid(Color32::from_rgb(100, 200, 100)))
        );

        // With OpenCode normalized status for semantic differentiation
        use crate::opencode::OpenCodeTransportStatus;
        // Permission + pending=true -> pulse
        assert_eq!(
            ai_badge_visual(
                AiCliStatus::Attention,
                None,
                Some(OpenCodeTransportStatus::Permission),
                None,
                false,
                None,
                true,
                None
            ),
            Some(AiBadgeVisual::Pulse(Color32::from_rgb(220, 180, 100)))
        );
        // Permission + pending=false -> solid (acknowledged)
        assert_eq!(
            ai_badge_visual(
                AiCliStatus::Attention,
                None,
                Some(OpenCodeTransportStatus::Permission),
                None,
                false,
                None,
                false,
                None
            ),
            Some(AiBadgeVisual::Solid(Color32::from_rgb(220, 180, 100)))
        );
        // Idle + pending=true -> pulse (turn complete notification)
        assert_eq!(
            ai_badge_visual(
                AiCliStatus::Attention,
                None,
                Some(OpenCodeTransportStatus::Idle),
                None,
                false,
                None,
                true,
                Some(OpenCodeAttentionReason::TurnComplete)
            ),
            Some(AiBadgeVisual::Pulse(Color32::from_rgb(100, 200, 100)))
        );
        // Idle + pending=false + TurnComplete -> hidden (acknowledged turn complete)
        assert_eq!(
            ai_badge_visual(
                AiCliStatus::Attention,
                None,
                Some(OpenCodeTransportStatus::Idle),
                None,
                false,
                None,
                false,
                Some(OpenCodeAttentionReason::TurnComplete)
            ),
            None
        );
        // Idle + pending=false + PermissionAsked -> amber solid (acknowledged but still needs action)
        assert_eq!(
            ai_badge_visual(
                AiCliStatus::Attention,
                None,
                Some(OpenCodeTransportStatus::Permission),
                None,
                false,
                None,
                false,
                Some(OpenCodeAttentionReason::PermissionAsked)
            ),
            Some(AiBadgeVisual::Solid(Color32::from_rgb(220, 180, 100)))
        );
        // Idle + pending=false + QuestionAsked -> amber solid (acknowledged but still needs action)
        assert_eq!(
            ai_badge_visual(
                AiCliStatus::Attention,
                None,
                Some(OpenCodeTransportStatus::Permission),
                None,
                false,
                None,
                false,
                Some(OpenCodeAttentionReason::QuestionAsked)
            ),
            Some(AiBadgeVisual::Solid(Color32::from_rgb(220, 180, 100)))
        );
        // Working status
        assert_eq!(
            ai_badge_visual(
                AiCliStatus::Attention,
                None,
                Some(OpenCodeTransportStatus::Working),
                None,
                false,
                None,
                false,
                None
            ),
            Some(AiBadgeVisual::Spinner(Color32::from_rgb(180, 180, 180)))
        );

        // With Claude normalized status (takes precedence over OpenCode)
        // Claude Permission + pending=true -> pulse (uses codex_attention_pending)
        assert_eq!(
            ai_badge_visual(
                AiCliStatus::Attention,
                None,
                Some(OpenCodeTransportStatus::Idle),
                Some(ClaudeTransportStatus::Permission),
                true, // codex_attention_pending used for Claude
                None,
                false,
                None
            ),
            Some(AiBadgeVisual::Pulse(Color32::from_rgb(220, 180, 100)))
        );
        assert_eq!(
            ai_badge_visual(
                AiCliStatus::Attention,
                None,
                None,
                Some(ClaudeTransportStatus::Idle),
                false,
                None,
                false,
                None
            ),
            Some(AiBadgeVisual::Solid(Color32::from_rgb(100, 200, 100)))
        );
    }

