    #[test]
    fn background_rerun_two_phase_interrupt_then_command() {
        // Regression: rerun sent the command into long-running processes.
        // Now two-phase: 1) Ctrl+C immediately, 2) command after settle.
        let ctx = Context::default();
        let mut app = test_app(
            [(
                1,
                test_terminal_entry_with_kind(1, 1, TerminalKind::Background),
            )],
            Some(1),
        );

        // Set up a terminal runtime with capture to verify what gets sent
        let (runtime, capture) = test_terminal_runtime_with_capture();
        app.terminals.insert(
            1,
            test_terminal_entry_with_runtime_and_kind(1, 1, runtime, TerminalKind::Background),
        );

        // Store a multi-line command in recent_inputs (simulating previous run)
        let full_command = "line1\nline2\n┃ final".to_owned();
        if let Some(terminal) = app.terminals.get_mut(&1) {
            terminal.recent_inputs.push_front(full_command.clone());
        }

        // Phase 1: rerun_command_in_terminal sends only Ctrl+C and queues the command.
        app.rerun_command_in_terminal(&ctx, 1, &full_command);
        capture.drain();

        // Verify only Ctrl+C was sent (phase 1), command is pending.
        let sent_after_phase1 = capture.bytes();
        assert_eq!(
            sent_after_phase1,
            vec![0x03],
            "phase 1 should send only Ctrl+C"
        );

        // Verify pending state is set correctly.
        let terminal = app.terminals.get(&1).expect("terminal 1");
        assert_eq!(
            terminal.pending_rerun_command,
            Some(full_command.clone()),
            "command should be pending after phase 1"
        );
        assert!(
            terminal.pending_rerun_since.is_some(),
            "pending timestamp should be set"
        );

        // Phase 2: manually advance pending_rerun_since so settle is satisfied.
        if let Some(terminal) = app.terminals.get_mut(&1) {
            terminal.pending_rerun_since =
                Some(Instant::now() - Duration::from_millis(PENDING_RERUN_SETTLE_MS + 10));
        }

        // Process pending reruns (this sends the actual command).
        app.process_pending_reruns(&ctx);
        capture.drain();

        // Verify total sent bytes: Ctrl+C (phase 1) + full command + \r (phase 2).
        let total_sent = capture.bytes();
        let mut expected_total = vec![0x03];
        expected_total.extend_from_slice(full_command.as_bytes());
        expected_total.push(b'\r');
        assert_eq!(
            total_sent, expected_total,
            "total should be Ctrl+C then full multi-line command with newlines preserved"
        );

        // Verify pending state is cleared after sending.
        let terminal = app.terminals.get(&1).expect("terminal 1");
        assert!(
            terminal.pending_rerun_command.is_none(),
            "pending command should be cleared after phase 2"
        );
        assert!(
            terminal.pending_rerun_since.is_none(),
            "pending timestamp should be cleared after phase 2"
        );
    }

    #[test]
    fn file_editor_text_edit_desired_rows_expands_for_long_files() {
        // Regression test: TextEdit::multiline must have enough rows for long files
        // to allow ScrollArea to scroll. Previously desired_rows was fixed to visible
        // viewport, causing scroll to not work for files longer than screen height.
        use super::{OpenFileBuffer, FILE_EDITOR_INPUT_ID};
        use egui::{Context, RawInput, FontDefinitions};

        let ctx = Context::default();
        ctx.set_fonts(FontDefinitions::default());

        // Create a buffer with many lines (simulating a long file)
        let long_content = "line\n".repeat(200); // 200 lines
        let buffer = OpenFileBuffer {
            project_id: 1,
            path: PathBuf::from("/project/src/long.rs"),
            display_name: "long.rs".to_owned(),
            text: long_content.clone(),
            saved_text: long_content,
            dirty: false,
            loaded_modified_at: None,
            last_error: None,
        };

        let line_count = buffer.text.lines().count();
        let visible_rows = 25; // Simulate visible viewport

        // The critical assertion: desired_rows must be at least line_count
        // so TextEdit allocates enough vertical space for scrolling
        let desired_rows = visible_rows.max(line_count);
        assert!(
            desired_rows >= line_count,
            "TextEdit must have at least {} rows for long file, had {}",
            line_count,
            desired_rows
        );

        // Verify line count is what we expect
        assert_eq!(line_count, 200, "should have 200 lines");
    }

