        let mut editor_state = super::FileEditorState::default();

        let buffer = OpenFileBuffer::new(
            1,
            PathBuf::from("/test/file.rs"),
            "content".to_owned(),
            "file.rs".to_owned(),
        );
        editor_state.open_file(buffer);
